// Browser evaluations of the equations beside each experiment. All units are explicit.
(() => {
'use strict';
const S=window.fundamentalStudies||={}, pi=Math.PI, rad=x=>x*pi/180;
const grid=(a,b,n=160)=>Array.from({length:n+1},(_,i)=>a+(b-a)*i/n);
const C=(name,x,f)=>({name,points:x.map(t=>[t,f(t)])}), P=(name,x,y)=>({name,points:[[x,y]]});
const f=x=>Number(x.toPrecision(5)).toString();
const add=(k,controls,xLabel,yLabel,calculate)=>S['complete-physics-'+k]={controls,xLabel,yLabel,calculate};
const sinc=x=>Math.abs(x)<1e-8?1:Math.sin(x)/x;
function integrate(fun,a,b,n=240){let s=fun(a)+fun(b);for(let i=1;i<n;i++)s+=(i%2?4:2)*fun(a+(b-a)*i/n);return s*(b-a)/(3*n);}
function bisect(fun,a,b){for(let i=0;i<65;i++){let c=(a+b)/2;if(fun(c)*fun(a)>0)a=c;else b=c;}return(a+b)/2;}
const cadd=(a,b)=>[a[0]+b[0],a[1]+b[1]], cmul=(a,b)=>[a[0]*b[0]-a[1]*b[1],a[0]*b[1]+a[1]*b[0]], cdiv=(a,b)=>{const d=b[0]**2+b[1]**2;return[(a[0]*b[0]+a[1]*b[1])/d,(a[1]*b[0]-a[0]*b[1])/d]}, abs=a=>Math.hypot(...a);
add('collision',[['Target / incident mass',.1,5,.1,1],['Incident speed (m/s)',.2,5,.1,2]],'Target / incident mass','Energy fraction',([r,u])=>{const x=grid(.1,5),t=q=>4*q/(1+q)**2;return{curves:[C('Transferred energy',x,t),C('Retained energy',x,q=>1-t(q)),P('Chosen ratio',r,t(r))],result:'Elastic collision with target initially at rest: outgoing speeds '+f(u*(1-r)/(1+r))+' and '+f(2*u/(1+r))+' m/s. Centre-of-mass speed '+f(u/(1+r))+' m/s.'};});
add('contact-pulse',[['Contact stiffness (N/m)',60,600,20,120],['Reduced mass (kg)',.01,.1,.005,.03],['Approach speed (m/s)',.2,4,.1,2]],'Time (ms)','Contact force (N)',([k,m,v])=>{const w=Math.sqrt(k/m),end=pi/w,force=t=>t<=end?m*v*w*Math.sin(w*t):0;return{curves:[{name:'Elastic contact pulse',points:grid(0,1.2*end).map(t=>[1000*t,force(t)])}],result:'Contact duration '+f(end*1000)+' ms; maximum force '+f(m*v*w)+' N; impulse 2μv = '+f(2*m*v)+' N s. Stiffness changes pulse shape, while impulse stays fixed.'};});
add('effective-orbit',[['Dimensionless energy',-.49,-.05,.01,-.37],['Angular-momentum scale',.5,2,.05,1]],'Radius / reference circular radius','Energy / reference GMm/r',([e,l])=>{const x=grid(.25,12,400),V=r=>l*l/(2*r*r)-1/r,d=1+2*e*l*l;return{curves:[C('Effective potential',x,V),C('Selected energy',x,()=>e)],result:d>=0?'Turning radii '+f((-1+Math.sqrt(d))/(2*e))+' and '+f((-1-Math.sqrt(d))/(2*e))+'. The horizontal energy line bounds the allowed radial motion.':'Selected energy is below this angular momentum’s minimum: no classically allowed orbit.'};});
add('mode-split',[['Coupling of squared frequencies',.01,.4,.01,.12],['Bare squared-frequency ratio',.3,1.7,.02,1]],'Bare squared-frequency ratio','Squared frequency / reference',([g,d])=>{const low=x=>(1+x-Math.hypot(1-x,2*g))/2,hi=x=>(1+x+Math.hypot(1-x,2*g))/2,x=grid(.3,1.7);return{curves:[C('Lower mode',x,low),C('Upper mode',x,hi),P('Selected lower',d,low(d)),P('Selected upper',d,hi(d))],result:'Squared eigenvalues '+f(low(d))+' and '+f(hi(d))+'. '+(low(d)>0?'Both modes are stable.':'A negative squared frequency signals an unstable stiffness matrix.')};});
add('oscillator-phase',[['Damping ratio ζ',.02,1,.02,.2]],'Drive / natural frequency','Displacement phase lag (degrees)',([z])=>({curves:[C('Selected damping',grid(0,3),r=>Math.atan2(2*z*r,1-r*r)*180/pi)],result:'Phase crosses 90° at frequency ratio 1. '+(z<Math.SQRT1_2?'Displacement amplitude peaks at '+f(Math.sqrt(1-2*z*z))+'.':'There is no nonzero-frequency displacement-amplitude maximum.')}));
add('duffing',[['Cubic stiffness × amplitude² / linear stiffness',0,3,.05,.5]],'Nonlinearity βA²/k','Period / small-amplitude period',([q])=>{const T=b=>2/pi*integrate(t=>1/Math.sqrt(1+b*(1+Math.sin(t)**2)/2),0,pi/2);return{curves:[C('Energy integral',grid(0,3,90),T),C('First-order expansion',grid(0,3),b=>1-3*b/8),P('Selected amplitude',q,T(q))],result:'Exact period ratio '+f(T(q))+'. The expansion is local to βA²/k ≪ 1; it becomes negative if extrapolated far enough.'};});
add('foucault',[['Latitude (degrees north)',-90,90,1,48],['Hours after release',0,12,.25,3]],'East displacement / initial amplitude','North displacement / initial amplitude',([lat,h])=>{const rate=2*pi/86164.1*Math.sin(rad(lat)),angle=-rate*h*3600;return{curves:[{name:'Initial swing axis',points:[[-1,0],[1,0]]},{name:'Swing axis at chosen time',points:[[-Math.cos(angle),-Math.sin(angle)],[Math.cos(angle),Math.sin(angle)]]}],result:'Leading-order Foucault azimuth drift '+f(-rate*180/pi*3600)+' degrees/hour. Directed axis rotates by '+f(angle*180/pi)+' degrees. Small swing amplitude and Earth rate much smaller than the pendulum frequency are assumed.'};});
add('cone',[['Cone half-angle (degrees)',10,80,1,30],['Endpoint azimuth separation (degrees)',5,180,5,120],['Slant radius (cm)',1,10,.5,5]],'Endpoint azimuth separation (degrees)','Intrinsic length (cm)',([a,p,r])=>{const q=x=>rad(x)*Math.sin(rad(a));return{curves:[C('Geodesic chord on unrolled cone',grid(0,180),x=>2*r*Math.sin(q(x)/2)),C('Constant-radius arc',grid(0,180),x=>r*q(x)),P('Selected separation',p,2*r*Math.sin(q(p)/2))],result:'Closest slant radius '+f(r*Math.cos(q(p)/2))+' cm. Cut and unroll the cone to obtain the straight chord; the planar distance is the intrinsic surface distance.'};});
add('guide-contact',[['Bottom speed squared / gR',.1,8,.1,3]],'Angle from the bottom (degrees)','Dimensionless force or speed squared',([u])=>{const end=u<=2?Math.acos(1-u/2):u<5?Math.acos((2-u)/3):pi,x=grid(0,end*180/pi);return{curves:[C('Normal force / mg',x,a=>u-2+3*Math.cos(rad(a))),C('Squared speed / gR',x,a=>u-2+2*Math.cos(rad(a)))],result:(u<=2?'Turns':u<5?'Loses contact':'Reaches the top')+' at '+f(end*180/pi)+'°. Curves stop at the first physical limit of the unilateral guide.'};});
add('logistic',[['Return-map parameter r',2.5,4,.002,3.6],['Initial state',.05,.95,.01,.2]],'Return number after 850 discarded iterates','Dimensionless state',([r,x0])=>{let x=x0,l=0;for(let j=0;j<850;j++)x=r*x*(1-x);const points=[];for(let j=0;j<160;j++){l+=Math.log(Math.max(1e-300,Math.abs(r*(1-2*x))));points.push([j,x]);x=r*x*(1-x);}return{curves:[{name:'Late return sequence',points}],result:'Finite-window Lyapunov estimate '+f(l/160)+' per return. Positive values suggest sensitive dependence; repeat with nearby initial states and longer notebooks before identifying an attractor.'};});
add('tidal',[['Central mass / Earth mass',.5,3,.1,1],['Laboratory radius / Earth radius',1,5,.1,1]],'Neighbour displacement (m)','Relative acceleration (µm/s²)',([m,r])=>{const g=3.986004418e14*m/(6.371e6*r)**3,x=grid(-20,20);return{curves:[C('Radial neighbour',x,s=>2*g*s*1e6),C('Transverse neighbour',x,s=>-g*s*1e6)],result:'Tidal eigenvalues (2,−1,−1) × '+g.toExponential(3)+' s⁻²; their sum is zero outside the source. Displacements must remain small compared with the laboratory radius.'};});
add('diffraction-chain',[['Number of unit cells',2,40,1,8],['Second-site / first-site form factor',0,1,.05,.25]],'Wavevector × cell length / 2π','Intensity / even-order peak',([n,b])=>({curves:[C('Finite two-site crystal',grid(.05,4.1,1200),u=>{const q=2*pi*u,den=Math.sin(q/2),l=Math.abs(den)<1e-10?1:(Math.sin(n*q/2)/(n*den))**2;return l*(1+b*b+2*b*Math.cos(q/2))/(1+b)**2;})],result:'Odd/even principal peak ratio = '+f(((1-b)/(1+b))**2)+'. Increasing cell count narrows the peaks; the basis determines systematic absences.'}));
add('diatomic',[['Heavy / light mass',1,10,.1,4]],'Wavevector × cell length / π','Frequency / √(K/m)',([r])=>{const x=grid(0,1),w=(q,s)=>Math.sqrt(1+1/r+s*Math.sqrt((1+1/r)**2-4/r*Math.sin(pi*q/2)**2));return{curves:[C('Acoustic',x,q=>w(q,-1)),C('Optical',x,q=>w(q,1))],result:'Zone-edge frequencies '+f(Math.sqrt(2/r))+' and '+f(Math.sqrt(2))+'. The gap closes at equal masses.'};});
add('state-count',[['Selected energy / reference',.1,3,.05,1]],'Energy / reference energy','Integrated states / reference count',([e])=>({curves:[1,2,3].map(d=>C(d+' spatial dimensions',grid(0,3),x=>x**(d/2))).concat([P('Selected 3D count',e,e**1.5)]),result:'At selected energy: 1D '+f(Math.sqrt(e))+', 2D '+f(e)+', 3D '+f(e**1.5)+'. Differentiating these curves gives the corresponding density of states.'}));
add('local-dos',[['Probe site in 40-site open chain',1,40,1,1],['Lorentzian broadening (eV)',.03,.3,.01,.08]],'Energy (eV)','Local density of states (states/eV)',([site,eta])=>{const dos=(E,j)=>{let s=0;for(let m=1;m<=40;m++){const q=pi*m/41,weight=2/41*Math.sin(q*j)**2;s+=weight*eta/(pi*((E+2*Math.cos(q))**2+eta*eta));}return s;};return{curves:[C('Selected site',grid(-3,3,400),e=>dos(e,site)),C('Central site',grid(-3,3,400),e=>dos(e,20))],result:'Nearest-neighbour hopping is 1 eV. Each full-energy spectral integral is one state per spin; finite plotted limits omit Lorentzian tails.'};});
add('carriers',[['Intrinsic density / donor density',.01,4,.01,1]],'Intrinsic density / donor density','Carrier density / donor density',([r])=>{const n=x=>(1+Math.sqrt(1+4*x*x))/2,p=x=>2*x*x/(1+Math.sqrt(1+4*x*x));return{curves:[C('Electrons',grid(0,4),n),C('Holes',grid(0,4),p),P('Selected electrons',r,n(r)),P('Selected holes',r,p(r))],result:'n−p = 1 donor-density unit; np = '+f(r*r)+'. Complete donor ionisation and nondegenerate equilibrium statistics are assumed.'};});
add('ambipolar',[['Temperature (K)',150,450,10,300],['Electron / hole background density',.1,10,.1,1],['Delay (µs)',0,10,.1,1]],'Position (µm)','Normalised carrier packet (1/µm)',([T,r,t])=>{const mn=.135,mp=.048,V=8.617333262e-5*T,dn=mn*V,dp=mp*V,da=(mn*r*dp+mp*dn)/(mn*r+mp),w=D=>Math.sqrt(100+2*D*1e6*t),x=grid(-6*w(dn),6*w(dn),300);return{curves:[[dn,'Electrons alone'],[dp,'Holes alone'],[da,'Neutral packet']].map(([D,n])=>C(n,x,v=>Math.exp(-.5*(v/w(D))**2)/(Math.sqrt(2*pi)*w(D)))),result:'Ambipolar diffusivity '+f(da)+' m²/s; packet rms width '+f(w(da))+' µm. Mobilities 0.135 and 0.048 m²/(V s); initial rms width 10 µm. Integrated carrier excess is conserved.'};});
add('landau-scale',[['Temperature (K)',2,80,1,20],['Effective mass / electron mass',.02,.5,.001,.067]],'Magnetic field (T)','Energy (meV)',([T,m])=>({curves:[C('Cyclotron level spacing',grid(0,8),B=>.115767636*B/m),C('Thermal energy',grid(0,8),()=>.08617333262*T)],result:'Thermal and cyclotron scales match at '+f(.08617333262*T*m/.115767636)+' T. Disorder broadening is a separate experimental scale.'}));
add('landau-potential',[['Quadratic coefficient a',-2,2,.05,-1],['Applied dimensionless field',-.5,.5,.02,0]],'Order parameter m','Reduced free-energy density',([a,h])=>({curves:[C('Landau potential',grid(-2,2,300),m=>a*m*m/2+m**4/4-h*m)],result:'The quartic coefficient is one. At zero field, minima lie at '+(a<0?'±'+f(Math.sqrt(-a)): 'm = 0')+'. A bulk potential does not predict a real specimen’s coercive field.'}));
add('dynes',[['Lifetime broadening Γ/Δ',.01,.5,.01,.1],['Gap Δ (meV)',.2,3,.1,1]],'Energy (meV)','Density / normal-state density',([g,d])=>{const rho=e=>{const z=[e/d,g],z2=cmul(z,z),a=z2[0]-1,b=z2[1],r=Math.hypot(a,b),sq=[Math.sqrt((r+a)/2),Math.sign(b||1)*Math.sqrt(Math.max(0,(r-a)/2))];return Math.abs(cdiv(z,sq)[0]);};return{curves:[C('Broadened superconducting spectrum',grid(-4*d,4*d,600),rho)],result:'Zero-energy density ratio '+f(g/Math.sqrt(1+g*g))+'. This density-of-states model precedes thermal and instrument convolution.'};});
add('impurity',[['Impurity / host mass',.22,.98,.01,.5]],'Site relative to impurity','Relative displacement',([m])=>{const q=m/(2-m);return{curves:[C('Infinite-chain local mode',grid(-12,12,24),j=>(-q)**Math.abs(j))],result:'Frequency '+f(2/Math.sqrt(m*(2-m)))+' × √(K/M), above host band edge 2. Decay length '+f(-1/Math.log(q))+' sites. Near equal masses use the finite-ring notebook to test finite-size effects.'};});
add('moire',[['Lattice mismatch',0,.08,.001,.013],['Relative twist (degrees)',0,8,.1,2]],'Horizontal position (nm)','Registry along y = 0',([d,a])=>{const g=2*pi/.246,dx=g*(1-Math.cos(rad(a))/(1+d)),dy=-g*Math.sin(rad(a))/(1+d),q=Math.hypot(dx,dy),L=q>1e-12?2*pi/q:100;return{curves:[C('Two perpendicular registry modulations',grid(-L,L,400),x=>(Math.cos(dx*x)+Math.cos(dy*x))/2)],result:q>1e-12?'Registry period '+f(L)+' nm; reciprocal mismatch magnitude '+f(q)+' nm⁻¹.':'Perfect registry: constant correlation and no finite moiré period.'};});
add('exciton',[['Reduced electron-hole mass / electron mass',.02,.5,.01,.1],['Relative permittivity',3,20,.5,8.5]],'Exciton principal quantum number','Binding below continuum (meV)',([m,e])=>{const R=13605.693*m/e**2;return{curves:[C('Hydrogenic exciton series',grid(1,8,7),n=>R/n**2)],result:'Effective Rydberg '+f(R)+' meV; effective Bohr radius '+f(.0529177*e/m)+' nm. Effective-mass and dielectric screening approximations require a sufficiently extended exciton.'};});
add('fmr',[['Saturation induction μ0M (T)',0,2,.05,1],['Gilbert damping α',.002,.1,.002,.01]],'Applied induction (T)','Frequency or linewidth (GHz)',([M,a])=>({curves:[C('In-plane film resonance',grid(.01,1),B=>28*Math.sqrt(B*(B+M))),C('Bare spin',grid(.01,1),B=>28*B),C('Weak-damping FWHM',grid(.01,1),B=>a*28*(2*B+M))],result:'Gyromagnetic ratio / 2π = 28 GHz/T. Uniform saturated film, in-plane field, no extra anisotropy; linewidth is the weak-damping estimate.'}));
add('pair-order',[['First-shell peak height',.5,4,.1,2],['First-shell width (nm)',.015,.08,.005,.04],['Number density (nm⁻³)',10,80,2,40]],'Separation (nm)','Radial pair correlation g(r)',([a,s,rho])=>{const g=r=>r<.18?0:1+a*Math.exp(-.5*((r-.28)/s)**2)+.45*Math.exp(-.5*((r-.52)/.06)**2),N=4*pi*rho*integrate(r=>r*r*g(r),.18,.4,400);return{curves:[C('Illustrative disordered-solid pair correlation',grid(0,.8,400),g)],result:'Coordination integrated over 0.18–0.40 nm = '+f(N)+'. This adjustable phenomenological profile demonstrates shell-volume weighting; it is not a fitted material structure.'};});
add('regular-solution',[['Reduced temperature T/Tc',.3,1.5,.02,.7]],'Mole fraction x','Mixing free energy / Ω',([t])=>{const g=x=>x*(1-x)+t/2*(x*Math.log(x)+(1-x)*Math.log(1-x)),x=grid(.001,.999,300);let msg='Above the critical temperature the symmetric model has one stable mixing minimum.';const curves=[C('Regular-solution free energy',x,g)];if(t<1){const xb=bisect(q=>1-2*q+t/2*Math.log(q/(1-q)),1e-12,.499999),xs=(1-Math.sqrt(1-t))/2;curves.push({name:'Common tangent',points:[[xb,g(xb)],[1-xb,g(xb)]]});msg='Binodal compositions '+f(xb)+', '+f(1-xb)+'; spinodal '+f(xs)+', '+f(1-xs)+'.';}return{curves,result:msg};});
add('fermi-area',[['Ellipsoid polar / equatorial radius',.4,4,.1,2]],'Field tilt from symmetry axis (degrees)','Extremal area / axial area',([r])=>({curves:[C('Ellipsoid',grid(0,85),a=>r/Math.hypot(Math.sin(rad(a)),r*Math.cos(rad(a)))),C('Open cylinder',grid(0,85),a=>1/Math.cos(rad(a)))],result:'Onsager frequency scales with the plotted area. An ellipsoid remains bounded at 90°; a perfect cylinder diverges in this ideal geometry.'}));
add('curie-dia',[['Curie coefficient C (K)',.01,.12,.005,.06],['Diamagnetic susceptibility magnitude',.00002,.0002,.00001,.0001]],'Temperature (K)','Magnetic susceptibility',([C0,d])=>({curves:[C('Curie contribution',grid(100,1000),T=>C0/T),C('Diamagnetic contribution',grid(100,1000),()=>-d),C('Sum',grid(100,1000),T=>C0/T-d)],result:'Sign change at T = '+f(C0/d)+' K within the independent-dipole, weak-field model. An ordering transition would invalidate extrapolation of this law.'}));
add('rotating-magnet',[['Rotation speed (rad/s)',10,500,10,100],['Radius (cm)',1,10,.5,5],['Internal induction (T)',.1,1.5,.1,1]],'Polar angle (degrees)','Surface potential (mV)',([w,a,B])=>{const scale=w*B*(a/100)**2/3*1000,p=a=>(3*Math.cos(rad(a))**2-1)/2;return{curves:[C('Conducting sphere',grid(0,180),x=>-scale*p(x)),C('Insulating sphere, same magnetisation',grid(0,180),x=>-.6*scale*p(x))],result:'Exterior quadrupole evaluated at r = a. Potentials are measured relative to infinity; B0 = 2μ0M/3. Insulating/conducting quadrupole ratio is 3/5.'};});
add('cylindrical',[['Fixed angle φ (degrees)',0,90,5,45]],'Radius r (m)','Gradient component (V/m)',([p])=>({curves:[C('Radial ∂V/∂r',grid(.1,2),r=>2*r*Math.cos(2*rad(p))),C('Azimuthal (1/r)∂V/∂φ',grid(.1,2),r=>-2*r*Math.sin(2*rad(p)))],result:'For V = (1 V/m²) r² cos(2φ), the Laplacian is zero: radial 4 cos(2φ) and angular −4 cos(2φ) cancel. The azimuthal derivative needs the metric factor 1/r.'}));
add('delay-force',[['Maximum light-crossing phase',.2,4,.1,2]],'Angular frequency × light-crossing delay','Self-force response / prefactor',([m])=>({curves:[C('Exact real: cos x − 1',grid(0,m),x=>Math.cos(x)-1),C('Exact imaginary: −sin x',grid(0,m),x=>-Math.sin(x)),C('Truncated real: −x²/2',grid(0,m),x=>-x*x/2),C('Truncated imaginary: −x',grid(0,m),x=>-x)],result:'For velocity proportional to exp(iωt), the delayed shell factor is exp(−iωτ)−1 with τ=2a/c. The differential approximation requires |ωτ| ≪ 1.'}));
add('spacetime',[['Observer speed v/c',-.9,.9,.05,.6]],'Laboratory coordinate x (light-seconds)','Laboratory ct (light-seconds)',([b])=>{const curves=[{name:'Light cone +',points:[[-2,-2],[2,2]]},{name:'Light cone −',points:[[-2,2],[2,-2]]},{name:'Moving time axis x = βct',points:[[-2*b,-2],[2*b,2]]},{name:'Moving simultaneity ct = βx',points:[[-2,-2*b],[2,2*b]]}];return{curves,result:'Lorentz factor γ = '+f(1/Math.sqrt(1-b*b))+'. Axes tilt with opposite roles; light directions remain invariant.'};});
add('strip-charge',[['Charge height / strip half-width',.1,3,.1,1],['Point charge (fC)',1,20,1,8]],'Lateral position / strip half-width','Induced strip charge (fC)',([h,q])=>({curves:[C('Grounded strip charge',grid(-4,4),x=>-q*(Math.atan((1-x)/h)+Math.atan((1+x)/h))/pi)],result:'At the centre the electrode receives '+f(-2*q*Math.atan(1/h)/pi)+' fC. Reciprocity converts the strip weighting potential into induced charge.'}));
add('evanescent-gap',[['Incidence angle (degrees)',43,80,1,50],['Wavelength (nm)',400,900,10,600]],'Air-gap thickness (nm)','Transmitted power fraction',([a,w])=>{const k=1.5*2*pi/w*Math.cos(rad(a)),q=2*pi/w*Math.sqrt((1.5*Math.sin(rad(a)))**2-1),F=(k*k+q*q)**2/(4*k*k*q*q);return{curves:[C('Frustrated total internal reflection',grid(0,1500),d=>1/(1+F*Math.sinh(q*d)**2))],result:'Symmetric TE gap with surrounding index 1.5. Amplitude decay length '+f(1/q)+' nm; critical angle 41.810°. At zero gap transmission is one.'};});
add('leaky-layers',[['Fraction occupied by layer 1',.05,.95,.05,.2],['Conductivity ratio σ2/σ1',1,1000,1,100]],'log10 frequency (Hz)','Apparent relative permittivity',([p,r])=>{const e=4*8.8541878128e-12,s1=1e-8,s2=s1*r,tau=e/(p*s2+(1-p)*s1);const eff=x=>{const w=2*pi*10**x,y1=[s1,w*e],y2=[s2,w*e];return cdiv(cmul(y1,y2),cadd(y2.map(v=>p*v),y1.map(v=>(1-p)*v)));};return{curves:[C('Effective storage permittivity',grid(-1,7),x=>eff(x)[1]/(2*pi*10**x*8.8541878128e-12))],result:'Both intrinsic relative permittivities equal 4. Interfacial relaxation frequency '+f(1/(2*pi*tau))+' Hz. A large low-frequency apparent permittivity can arise from conductivity contrast.'};});
add('open-domain',[['Grounded outer radius / sphere radius',2.2,15,.2,5]],'Radius / sphere radius','Dipole radial amplitude',([R])=>({curves:[C('Open domain',grid(1,R),r=>1/r**2),C('Grounded outer wall',grid(1,R),r=>(1/r**2-r/R**3)/(1-1/R**3))],result:'Relative boundary error at r/a=2 is '+f(7/(R**3-1))+'. This error remains after solving the discretised bounded-domain problem accurately.'}));
add('piezo-load',[['Added mass fraction',0,.04,.001,.01],['Parallel capacitance (pF)',5,30,1,15]],'Frequency (kHz)','Terminal admittance magnitude (µS)',([eta,cp])=>{const cm=.25e-12,c0=cp*1e-12,fs=1e5,L=1/((2*pi*fs)**2*cm),R=2*pi*fs*L/600,Y=(f,e)=>{const w=2*pi*f,react=w*L*(1+e)-1/(w*cm),den=R*R+react*react;return Math.hypot(R/den,w*c0-react/den)*1e6;};return{curves:[C('Unloaded',grid(96,103,1000),f=>Y(1000*f,0)),C('Loaded',grid(96,103,1000),f=>Y(1000*f,eta))],result:'Loaded lossless series/parallel frequencies '+f(fs/Math.sqrt(1+eta))+' / '+f(fs*Math.sqrt((1+cm/c0)/(1+eta)))+' Hz. Quality factor 600; motional capacitance 0.25 pF.'};});
add('four-probe',[['Probe spacing / film thickness',.1,12,.1,2]],'Spacing / thickness','Scaled resistance (V/I)h/ρ',([z])=>{const resistance=x=>{let s=0;for(let n=1;n<=1500;n++){const a=Math.hypot(x,2*n),b=Math.hypot(2*x,2*n);s+=3*x*x/(a*b*(a+b));}return(1/(2*x)+2*s)/pi;};return{curves:[C('Finite-thickness image sum',grid(.1,12,150),resistance),C('Bulk limit',grid(.1,12),x=>1/(2*pi*x)),C('Thin sheet',grid(.1,12),()=>Math.log(2)/pi),P('Selected spacing',z,resistance(z))],result:'Thin-sheet inference bias '+f(pi*resistance(z)/Math.log(2)-1)+'. Image sum uses 1500 pairs; the notebook checks its truncation with a longer sum.'};});
add('gaussian-packet',[['Elapsed time / spreading time',0,5,.1,1],['Initial rms width (nm)',.5,3,.1,1]],'Position (nm)','Probability density (1/nm)',([t,s])=>{const w=s*Math.hypot(1,t),x=grid(-6*w,6*w,360),gauss=(v,a)=>Math.exp(-v*v/(2*a*a))/(Math.sqrt(2*pi)*a);return{curves:[C('Initial packet',x,v=>gauss(v,s)),C('Free evolved packet',x,v=>gauss(v,w))],result:'Rms width '+f(w)+' nm. The full spatial integral stays one; spreading does not reduce total probability.'};});
add('step-scattering',[['Selected energy / step height',.1,5,.05,2]],'Energy / potential-step height','Probability-current fraction',([e])=>{const R=x=>x<=1?1:((Math.sqrt(x)-Math.sqrt(x-1))/(Math.sqrt(x)+Math.sqrt(x-1)))**2;return{curves:[C('Reflected flux',grid(.05,5,400),R),C('Transmitted flux',grid(.05,5,400),x=>1-R(x)),P('Selected transmission',e,1-R(e))],result:'R + T = 1. At the selected energy T = '+f(1-R(e))+'. The step extends to infinity; evanescent density below threshold carries no transmitted current.'};});
add('oscillator-density',[['Oscillator length (nm)',.5,3,.1,1],['Excited-state admixture probability',0,1,.05,0],['Relative phase (degrees)',0,180,5,0]],'Position (nm)','Probability density (1/nm)',([l,p,a])=>{const x=grid(-5*l,5*l,400),n=v=>Math.exp(-((v/l)**2))/(Math.sqrt(pi)*l);return{curves:[C('Ground state',x,n),C('First excited state',x,v=>2*(v/l)**2*n(v)),C('Coherent superposition',x,v=>n(v)*(1-p+2*p*(v/l)**2+2*Math.sqrt(2*p*(1-p))*(v/l)*Math.cos(rad(a))))],result:'Ground and first-excited basis states are orthogonal. Changing the relative phase alters interference while preserving the integrated probability.'};});
add('level-mixing',[['Coupling (energy units)',0,.8,.02,.3],['Selected detuning',-2,2,.05,0]],'Bare detuning','Energy',([g,d])=>({curves:[C('Lower eigenvalue',grid(-2,2),x=>-Math.hypot(x/2,g)),C('Upper eigenvalue',grid(-2,2),x=>Math.hypot(x/2,g)),P('Selected lower',d,-Math.hypot(d/2,g)),P('Selected upper',d,Math.hypot(d/2,g))],result:'Minimum gap = 2g = '+f(2*g)+'. At nonzero coupling the eigenvectors exchange bare-state character through the avoided crossing.'}));
add('rabi',[['Detuning / resonant Rabi frequency',0,3,.05,1],['Pulse length in resonant π times',.1,4,.1,1]],'Time / resonant π-pulse time','Excited population',([d,T])=>{const omega=Math.hypot(1,d),p=t=>Math.sin(pi*t*omega/2)**2/(omega*omega);return{curves:[C('Detuned drive',grid(0,4,400),p),C('Resonant drive',grid(0,4,400),t=>Math.sin(pi*t/2)**2),P('End of selected pulse',T,p(T))],result:'Maximum excited population '+f(1/(1+d*d))+'; pulse-end population '+f(p(T))+'. Rotating-wave, coherent two-level model.'};});
add('linear-variational',[['Trial width s',.2,2.5,.02,.96]],'Gaussian trial width s','Reduced energy',([s])=>{const E=x=>1/(4*x*x)+x/Math.sqrt(pi);return{curves:[C('Kinetic',grid(.2,2.5),x=>1/(4*x*x)),C('Potential',grid(.2,2.5),x=>x/Math.sqrt(pi)),C('Total',grid(.2,2.5),E),P('Selected trial',s,E(s))],result:'Optimal width (√π/2)^(1/3) = '+f((Math.sqrt(pi)/2)**(1/3))+'. Selected energy '+f(E(s))+'. This is a variational upper bound for a linear |x| potential.'};});
add('cusp-trial',[['Attractive contact strength',.5,3,.1,1],['Inverse-length scale / optimum',.2,2.5,.05,1]],'Position (model lengths)','Probability density',([g,s])=>{const b=2*g/Math.sqrt(pi)*s,a=g*s,x=grid(-5/g,5/g,400);return{curves:[C('Gaussian trial',x,x=>b/Math.sqrt(pi)*Math.exp(-((b*x)**2))),C('Cusp trial',x,x=>a*Math.exp(-2*a*Math.abs(x)))],result:'Gaussian / cusp trial energies '+f(b*b/4-g*b/Math.sqrt(pi))+' / '+f(a*a/2-g*a)+'. Exact ground energy −g²/2 = '+f(-g*g/2)+'. Only the cusp family can satisfy the contact derivative jump.'};});
function eigenSymmetric(a){const n=a.length,m=a.map(r=>r.slice());for(let it=0;it<80*n*n;it++){let p=0,q=1,big=0;for(let i=0;i<n;i++)for(let j=i+1;j<n;j++)if(Math.abs(m[i][j])>big){big=Math.abs(m[i][j]);p=i;q=j;}if(big<1e-11)break;const angle=.5*Math.atan2(2*m[p][q],m[q][q]-m[p][p]),c=Math.cos(angle),s=Math.sin(angle),aa=m[p][p],bb=m[q][q],ab=m[p][q];m[p][p]=c*c*aa-2*c*s*ab+s*s*bb;m[q][q]=s*s*aa+2*c*s*ab+c*c*bb;m[p][q]=m[q][p]=0;for(let k=0;k<n;k++)if(k!==p&&k!==q){const u=m[k][p],v=m[k][q];m[k][p]=m[p][k]=c*u-s*v;m[k][q]=m[q][k]=s*u+c*v;}}return m.map((r,i)=>r[i]).sort((a,b)=>a-b);}
add('ritz-basis',[['Potential rise / untilted ground energy',0,30,1,12]],'Number of sine basis functions','Energy / untilted ground energy',([tilt])=>{const eig=n=>eigenSymmetric(Array.from({length:n},(_,i)=>Array.from({length:n},(_,j)=>i===j?(i+1)**2+tilt/2:((i+j)%2? -8*tilt*(i+1)*(j+1)/(pi*pi*((i+1)**2-(j+1)**2)**2):0))));const x=grid(2,14,12),v=x.map(eig),ref=eig(24);return{curves:[{name:'Lowest Ritz energy',points:x.map((n,i)=>[n,v[i][0]])},{name:'Second Ritz energy',points:x.map((n,i)=>[n,v[i][1]])},C('24-function lowest reference',x,()=>ref[0]),C('24-function second reference',x,()=>ref[1])],result:'Nested sine spaces preserve the variational bounds. Browser reference has 24 functions; the supplied OneSimulation script uses 64. Untilting recovers n² exactly.'};});
add('billiard',[['Aspect ratio Lx/Ly at fixed area',.5,2,.05,1]],'Aspect ratio at fixed area','Energy / square ground half-energy',([a])=>{const pairs=[[1,1],[1,2],[2,1],[2,2]],x=grid(.5,2);return{curves:pairs.map(([m,n])=>C('Mode ('+m+','+n+')',x,r=>m*m/r+n*n*r)).concat([P('Selected (1,2)',a,1/a+4*a)]),result:'E12 = '+f(1/a+4*a)+', E21 = '+f(4/a+a)+'. Their crossing is exact for the separable hard-wall rectangle.'};});
add('echo',[['Noise correlation time (ms)',.1,5,.1,1],['Rms detuning (rad/ms)',.1,3,.1,1]],'Evolution time (ms)','Normalised coherence',([tau,s])=>{const chi=(t,echo)=>{const x=t/tau;return s*s*tau*tau*(echo?(x<1e-3?x**3/12-x**4/32:x+4*Math.expm1(-x/2)-Math.expm1(-x)):(x<1e-3?x*x/2-x**3/6:x+Math.expm1(-x)));};return{curves:[C('Free induction',grid(0,10),t=>Math.exp(-chi(t,false))),C('Midpoint Hahn echo',grid(0,10),t=>Math.exp(-chi(t,true))),C('Static-noise free induction',grid(0,10),t=>Math.exp(-s*s*t*t/2))],result:'Stationary Gaussian noise with exponential covariance. The echo suppresses slowly varying noise; faster noise cannot be completely refocused.'};});
add('zeno',[['Total pulse area / π',.1,3,.1,1],['Intermediate measurements',1,100,1,8]],'Fraction of total drive time','Probability',([a,n])=>{const area=a*pi,x=grid(0,1,300),times=grid(0,n,n);return{curves:[C('No measurement',x,t=>Math.cos(area*t/2)**2),{name:'Passed every test',points:times.map(j=>[j/n,Math.cos(area/(2*n))**(2*j)])},{name:'Ground at this test, records unread',points:times.map(j=>[j/n,(1+Math.cos(area/n)**j)/2])}],result:'Selective survival '+f(Math.cos(area/(2*n))**(2*n))+'; unread final ground population '+f((1+Math.cos(area/n)**n)/2)+'. Ideal instantaneous projective measurements are assumed.'};});
add('geometric-phase',[['Third-state longitude (degrees)',-175,175,5,90]],'Real cyclic overlap','Imaginary cyclic overlap',([a])=>{const p=rad(a),z=[(1+Math.cos(p))/4,Math.sin(p)/4];return{curves:[{name:'Cyclic-overlap locus',points:grid(-pi,pi,360).map(t=>[(1+Math.cos(t))/4,Math.sin(t)/4])},{name:'Selected overlap',points:[[0,0],z]}],result:'Overlap modulus '+f(Math.hypot(...z))+'; overlap phase '+f(Math.atan2(z[1],z[0]))+' rad. Parallel-transport phase has the opposite sign. Arbitrary individual state phases cancel.'};});
add('born',[['Repeated-scattering magnitude |λI|',.1,1.4,.02,.7]],'Number of Born terms','log10 relative error',([r])=>({curves:[C('Exact separable-model truncation error',grid(1,30,29),n=>n*Math.log10(r))],result:'Relative error is |λI|^N. '+(r<1?'The geometric series converges.':r===1?'Errors do not decay.':'Adding terms increases the error: the Born series does not converge.')}));
add('thermal-emission',[['Transition frequency (THz)',1,100,.5,20],['Bath temperature (K)',50,2000,25,300]],'Bath temperature (K)','Stimulated / spontaneous downward rate',([nu,T])=>{const energyK=47.9924307*nu,rate=t=>1/Math.expm1(energyK/t);return{curves:[C('Thermal occupation',grid(50,2000),rate),C('Equal downward rates',grid(50,2000),()=>1),P('Selected bath',T,rate(T))],result:'At selected bath stimulated/spontaneous = '+f(rate(T))+'. Equality occurs at '+f(energyK/Math.log(2))+' K; the transition energy is hν.'};});
add('spin-copy',[['Input polar angle (degrees)',0,180,5,90]],'Computational-basis outcome index (0=00, 1=01, 2=10, 3=11)','Measurement probability',([a])=>{const p=Math.cos(rad(a)/2)**2;return{curves:[{name:'Calibrated basis copier',points:[[0,p],[1,0],[2,0],[3,1-p]]},{name:'Two independently prepared copies',points:[[0,p*p],[1,p*(1-p)],[2,p*(1-p)],[3,(1-p)**2]]}],result:'The copier creates correlated records. At a superposition input they differ from two independent copies; at either calibrated basis state they agree.'};});
add('vdw',[['Reduced temperature T/Tc',.65,1.3,.01,.9]],'Reduced volume V/Vc','Reduced pressure p/pc',([t])=>({curves:[C('Homogeneous van der Waals isotherm',grid(.42,5,500),v=>8*t/(3*v-1)-3/(v*v))],result:'The derivative is −24Tr/(3Vr−1)² + 6/Vr³. A positive derivative means negative compressibility. Below Tc equilibrium requires a coexistence construction; the displayed loop is the homogeneous equation.'}));
add('clausius',[['Molar latent heat (kJ/mol)',25,55,.5,40.5],['Anchor boiling temperature (K)',340,400,2,374]],'Temperature (K)','Vapour pressure (kPa)',([L,T0])=>({curves:[C('Constant-latent-heat approximation',grid(300,400),T=>101.325*Math.exp(-1000*L/8.314462618*(1/T-1/T0)))],result:'Pressure is anchored to 101.325 kPa at '+T0+' K. Ideal vapour, negligible liquid molar volume and constant latent heat are assumed.'}));
add('two-level',[['Energy gap / kB (K)',50,600,10,200]],'Temperature (K)','Heat capacity / kB per system',([gap])=>({curves:[C('Two-level heat capacity',grid(5,700,400),T=>{const x=gap/T,w=Math.exp(-x);return x*x*w/(1+w)**2;})],result:'The nondegenerate two-level maximum lies at T = gap/2.399357 = '+f(gap/2.39935728)+' K.'}));
add('effusion-mixture',[['Heavy / light molecular mass',1,16,.5,4],['Initial light-species fraction',.05,.95,.05,.5]],'Time / heavy-species depletion time','Light-species fraction',([m,p])=>{const r=Math.sqrt(m),a=t=>p*Math.exp(-r*t),b=t=>(1-p)*Math.exp(-t),x=grid(0,5);return{curves:[C('Remaining vessel',x,t=>a(t)/(a(t)+b(t))),C('Instantaneous beam',x,t=>r*a(t)/(r*a(t)+b(t))),C('Collected since start',x,t=>t===0?r*p/(r*p+1-p):p*(-Math.expm1(-r*t))/(p*(-Math.expm1(-r*t))+(1-p)*(-Math.expm1(-t))))],result:'Light depletion rate is '+f(r)+' times the heavy rate. Temperature is fixed and the aperture remains in the molecular-effusion regime.'};});
add('speed-law',[['Temperature (K)',100,800,10,300],['Molecular mass (atomic mass units)',2,80,2,28]],'Speed (m/s)','Probability density per m/s',([T,m])=>{const v=Math.sqrt(2*1.380649e-23*T/(m*1.6605390666e-27));return{curves:[C('Gas particles',grid(0,4*v),s=>4/Math.sqrt(pi)*(s/v)**2*Math.exp(-((s/v)**2))/v),C('Effusing flux',grid(0,4*v),s=>2*(s/v)**3*Math.exp(-((s/v)**2))/v)],result:'Gas mode '+f(v)+' m/s; effusive mode '+f(v*Math.sqrt(1.5))+' m/s. Both distributions integrate to one over all speeds.'};});
add('einstein-debye',[['Characteristic temperature (K)',100,800,20,300]],'Temperature (K)','Heat capacity / (3NkB)',([theta])=>{const ein=T=>{const x=theta/T,e=Math.exp(-x);return x*x*e/(1-e)**2;},deb=T=>{const x=theta/T;return 3/(x**3)*integrate(v=>v===0?0:v**4*Math.exp(-v)/(-Math.expm1(-v))**2,0,Math.min(x,80),400);};return{curves:[C('Einstein single-frequency model',grid(5,800,180),ein),C('Debye acoustic continuum',grid(5,800,180),deb)],result:'Both approach the Dulong–Petit value one at high temperature. Debye retains low-frequency acoustic modes and gives a T³ law at low temperature.'};});
add('thermal-entropy',[['Initial hot-body temperature (K)',310,500,10,350],['Conductance (W/K)',1,20,1,4],['Heat capacity of each body (J/K)',100,1000,50,500]],'Time (s)','Entropy change (J/K)',([Th,G,C0])=>{const Tc=250,Tf=(Th+Tc)/2,tau=C0/(2*G),x=grid(0,5*tau),hot=t=>Tf+(Th-Tc)/2*Math.exp(-t/tau),cold=t=>Tf-(Th-Tc)/2*Math.exp(-t/tau);return{curves:[C('Hot body',x,t=>C0*Math.log(hot(t)/Th)),C('Cold body',x,t=>C0*Math.log(cold(t)/Tc)),C('Isolated pair',x,t=>C0*Math.log(hot(t)*cold(t)/(Th*Tc)))],result:'Equilibrium temperature '+f(Tf)+' K; entropy increase '+f(C0*Math.log(Tf*Tf/(Th*Tc)))+' J/K. Two equal heat capacities, constant conductance and no external losses.'};});
add('thermometer',[['Gap / kB (K)',100,800,20,400],['Observed excited count out of 200',0,100,1,40]],'Trial temperature (K)','Likelihood / maximum on grid',([gap,k])=>{const x=grid(10,1200,500),ll=T=>-k*gap/T-200*Math.log1p(Math.exp(-gap/T)),v=x.map(ll),max=Math.max(...v);return{curves:[{name:'Likelihood for selected record',points:x.map((T,i)=>[T,Math.exp(v[i]-max)])}],result:k===0?'No excited observations: the maximum is at the T→0 boundary.':k===100?'The positive-temperature maximum is at T→∞.':'Positive-temperature maximum '+f(gap/Math.log((200-k)/k))+' K. The observed count is adjustable; no fresh random record is silently generated.'};});
add('negative-temperature',[['Number of bounded two-level sites',4,100,2,20],['Selected excitation fraction',.05,.95,.05,.75]],'Fraction of sites excited','Shell entropy / (NkB)',([N,p])=>{const entropy=[0];for(let k=0;k<N;k++)entropy.push(entropy.at(-1)+Math.log((N-k)/(k+1)));const k=Math.min(N-1,Math.floor(p*N));return{curves:[{name:'Exact log binomial multiplicity',points:entropy.map((s,n)=>[n/N,s/N])},{name:'Adjacent shells used for temperature',points:[[k/N,entropy[k]/N],[(k+1)/N,entropy[k+1]/N]]}],result:'Finite difference βε = ln[(N−n)/(n+1)] = '+f(Math.log((N-k)/(k+1)))+'. Above half filling entropy decreases with energy, giving negative temperature for this bounded spectrum.'};});
add('sedimentation',[['Particle radius (µm)',.1,1,.05,.5],['Particle minus fluid density (kg/m³)',-100,100,5,50],['Independent observations',100,3000,100,1200]],'Height of slice centre (µm)','Expected counts in 12 equal slices',([r,d,N])=>{const slope=4*pi/3*(r*1e-6)**3*d*9.80665/(1.380649e-23*293)*1e-6,x=grid(2.5,57.5,11),log=x.map(z=>-slope*z),top=Math.max(...log),w=log.map(v=>Math.exp(v-top)),sum=w.reduce((a,b)=>a+b,0);return{curves:[{name:'Expected histogram',points:x.map((z,i)=>[z,N*w[i]/sum])},C('Density matched',x,()=>N/12)],result:'Temperature 293 K; signed gravitational slope '+f(slope)+' µm⁻¹. Counts sum to '+N+'. The notebook adds seeded multinomial sampling to these expectations.'};});
add('nernst',[['Temperature (K)',250,450,10,300],['Electrons per reaction',1,4,1,2],['Standard voltage (V)',.2,1.5,.05,1.1]],'log10 activity quotient Q','Reversible cell voltage (V)',([T,n,E])=>({curves:[C('Nernst equation',grid(-6,6),q=>E-8.314462618*T/(n*96485.33212)*Math.log(10)*q)],result:'Slope '+f(-8.314462618*T/(n*96485.33212)*Math.log(10))+' V per decade. Activities are dimensionless; irreversible overpotentials are excluded.'}));
add('doppler',[['Approach speed / sound speed',0,.7,.02,.2]],'Approach speed / sound speed','Observed / emitted frequency',([b])=>({curves:[C('Moving source, fixed receiver',grid(0,.7),x=>1/(1-x)),C('Moving receiver, fixed source',grid(0,.7),x=>1+x),P('Selected source speed',b,1/(1-b))],result:'At selected speed: moving-source factor '+f(1/(1-b))+'; moving-receiver factor '+f(1+b)+'. The medium defines the rest frame.'}));
add('standing-wave',[['Reflected field amplitude ratio',0,.95,.05,.6],['Reflection phase (degrees)',-180,180,10,0]],'Position / wavelength','Field-envelope amplitude / incident amplitude',([r,p])=>({curves:[C('Standing-wave envelope',grid(0,2,400),x=>Math.sqrt(1+r*r+2*r*Math.cos(4*pi*x+rad(p))))],result:'Maximum/minimum '+f(1+r)+' / '+f(1-r)+'. Standing-wave ratio '+f((1+r)/(1-r))+'. Minima are spaced by half a wavelength.'}));
add('pulse-width',[['Distance / dispersion length',0,5,.1,3],['Initial pulse rms duration (fs)',10,100,5,30]],'Retarded time (fs)','Normalised intensity (1/fs)',([z,s])=>{const w=s*Math.hypot(1,z),g=(x,t)=>Math.exp(-.5*(x/t)**2)/(Math.sqrt(2*pi)*t),x=grid(-5*w,5*w,400);return{curves:[C('Initial pulse',x,x=>g(x,s)),C('Dispersed pulse',x,x=>g(x,w))],result:'Rms duration '+f(w)+' fs. Full pulse energy is conserved under quadratic phase dispersion; a finite detector gate can lose part of the broadened pulse.'};});
add('retarder',[['Plate-axis angle (degrees)',0,90,5,45],['Selected retardance / π',0,4,.05,.5]],'Retardance / π','Transmission through crossed polarisers',([a,d])=>{const T=x=>Math.sin(2*rad(a))**2*Math.sin(pi*x/2)**2;return{curves:[C('Lossless retarder and analyser',grid(0,4),T),P('Selected retardance',d,T(d))],result:'Selected transmitted fraction '+f(T(d))+'. Intensity alone repeats every 2π of retardance and does not uniquely identify its order.'};});
add('double-slit',[['Slit spacing / slit width',1,6,.1,3],['Relative incident phase (degrees)',0,180,10,0]],'Slit width × sin θ / wavelength','Intensity / in-phase axial peak',([d,p])=>({curves:[C('Two finite slits',grid(-3,3,1000),u=>sinc(pi*u)**2*Math.cos(pi*d*u+rad(p)/2)**2),C('Single-slit envelope',grid(-3,3,1000),u=>sinc(pi*u)**2)],result:'For zero phase and integer d/a, the corresponding interference order is removed by the first envelope zero. Fraunhofer scalar model with equal slit illumination.'}));
add('fabry-perot',[['Mirror power reflectivity',.05,.95,.05,.8]],'Round-trip phase / π','Transmitted power fraction',([R])=>({curves:[C('Symmetric lossless Fabry–Pérot',grid(-2,2,1000),p=>1/(1+4*R/(1-R)**2*Math.sin(pi*p/2)**2))],result:'Finesse coefficient 4R/(1−R)² = '+f(4*R/(1-R)**2)+'. Stronger reflection narrows each resonance while the peak remains one.'}));
add('grating',[['Illuminated grooves',5,100,5,20]],'Phase offset from principal order (rad)','Normalised intensity',([N])=>({curves:[C('Finite uniform grating',grid(-.8,.8,1200),x=>Math.abs(x)<1e-10?1:(Math.sin(N*x/2)/(N*Math.sin(x/2)))**2)],result:'First zeros at ±2π/N = ±'+f(2*pi/N)+' radians. Absolute peak intensity scales as N² at fixed field per groove.'}));
add('gouy',[['Waist radius (µm)',10,100,5,30],['Reference phase (degrees)',-180,180,10,0]],'Axial distance (mm)','Normalised field quadrature',([w,p])=>{const zr=pi*w*w/.633/1000,xx=grid(-4*zr,4*zr,400);return{curves:[C('In-phase',xx,z=>(Math.cos(rad(p))+z/zr*Math.sin(rad(p)))/(1+(z/zr)**2)),C('Quadrature',xx,z=>(Math.sin(rad(p))-z/zr*Math.cos(rad(p)))/(1+(z/zr)**2))],result:'Wavelength 633 nm; Rayleigh range '+f(zr)+' mm. After removing kz the phase is −atan(z/zR); reference phase rotates the measured quadratures.'};});
add('gaussian-curvature',[['Photographed field radius (mm)',.2,.8,.02,.4],['Magnitude of wavefront radius (m)',.2,2,.05,.6]],'Distance after photograph (m)','Field radius (mm)',([w,R])=>{const zr=pi*(w/1000)**2/633e-9,x=grid(0,2),width=(z,r)=>w*Math.hypot(1+z/r,z/zr);return{curves:[C('Initially diverging phase',x,z=>width(z,R)),C('Initially converging phase',x,z=>width(z,-R))],result:'Identical initial intensities, opposite quadratic phases. Converging waist at z = '+f(R*zr*zr/(R*R+zr*zr))+' m. Paraxial Gaussian model at 633 nm.'};});
function J1(x){return integrate(t=>Math.cos(t-x*Math.sin(t)),0,pi,200)/pi;}
add('stellar-disk',[['Angular diameter (milliarcseconds)',.5,5,.1,1.5],['Wavelength (nm)',400,1000,20,600]],'Projected baseline (m)','Absolute fringe visibility',([d,w])=>{const theta=d*4.848136811e-9;return{curves:[C('Uniform circular stellar disk',grid(0,300,220),B=>{const x=pi*B*theta/(w*1e-9);return x<1e-8?1:Math.abs(2*J1(x)/x);})],result:'First visibility zero near '+f(1.21966989*w*1e-9/theta)+' m. Monochromatic uniform disk; limb darkening and bandwidth are omitted.'};});
add('talbot',[['Propagation distance / paraxial Talbot length',0,1,.025,.25],['Grating period (µm)',3,20,.5,10],['Second-harmonic mask phase (degrees)',0,180,10,0]],'Lateral position / period','Intensity / incident intensity',([z,d,p])=>{const lambda=.633,k=2*pi/lambda,zt=2*d*d/lambda,mask=x=>.58+.22*Math.cos(2*pi*x)+.12*Math.cos(4*pi*x+rad(p));const field=(x,exact)=>{let sum=[.58,0];for(const m of [-2,-1,1,2]){const amp=Math.abs(m)===1?.11:.06,offset=Math.abs(m)===2?Math.sign(m)*rad(p):0,phase=2*pi*m*x+offset+(exact?(Math.sqrt(k*k-(2*pi*m/d)**2)-k)*zt*z:-2*pi*m*m*z);sum=cadd(sum,[amp*Math.cos(phase),amp*Math.sin(phase)]);}return abs(sum)**2;};return{curves:[C('Initial mask intensity',grid(0,1,300),x=>mask(x)**2),C('Exact angular spectrum',grid(0,1,300),x=>field(x,true)),C('Paraxial propagation',grid(0,1,300),x=>field(x,false))],result:'Wavelength 633 nm; paraxial Talbot length '+f(zt)+' µm. This smooth mask contains only orders 0, ±1, ±2, so their exact propagation is evaluated directly.'};});
add('doublet',[['Wavelength splitting (nm)',.1,2,.05,.6],['Second / first line intensity',.1,3,.1,1]],'Mirror displacement (mm)','Local fringe visibility',([d,r])=>{const ds=Math.abs(1/589e-9-1/((589+d)*1e-9));return{curves:[C('Incoherent spectral doublet',grid(0,1.5,700),x=>Math.hypot(1+r*Math.cos(4*pi*ds*x/1000),r*Math.sin(4*pi*ds*x/1000))/(1+r))],result:'First contrast minimum '+f(1000/(4*ds))+' mm; minimum visibility '+f(Math.abs(1-r)/(1+r))+'. Wavelength of first line is 589 nm.'};});
add('telescope',[['Eyepiece focal length (mm)',10,50,2,20],['Field angle (degrees)',0,2,.1,.5]],'Axial distance (mm)','Paraxial ray height (mm)',([f2,a])=>{const f1=200,L=f1+f2,u=rad(a),curves=[];for(const h of [-10,-5,0,5,10]){const v=u-h/f1,y=h+L*v,out=v-y/f2;curves.push({name:'Objective height '+h+' mm',points:[[-30,h-30*u],[0,h],[L,y],[L+100,y+100*out]]});}return{curves,result:'Afocal spacing '+f(L)+' mm; angular magnification −'+f(f1/f2)+'. A 20 mm objective gives an exit pupil '+f(20*f2/f1)+' mm in diameter, '+f(f2*(1+f2/f1))+' mm after the eyepiece.'};});
add('aberration',[['Coma coefficient (µm)',0,4,.1,1],['Astigmatism coefficient (µm)',0,4,.1,1],['Defocus coefficient (µm)',-4,4,.1,0]],'Horizontal ray intercept (µm)','Vertical ray intercept (µm)',([c,a,d])=>{const points=[];for(let ring=1;ring<=8;ring++)for(let j=0;j<=80;j++){const u=ring/8*Math.cos(2*pi*j/80),v=ring/8*Math.sin(2*pi*j/80);points.push([20*(c*(3*u*u+v*v)+2*(a+d)*u),20*(2*c*u*v+2*(d-a)*v)]);}return{curves:[{name:'Pupil rings mapped by wavefront gradient',points}],result:'W = C u(u²+v²) + A(u²−v²) + D(u²+v²), with f/a=20. D=±A gives the two astigmatic line foci when C=0. This geometrical intercept diagram omits diffraction.'};});
add('photocentre',[['Companion mass fraction',.1,.9,.05,.4],['Companion light fraction',0,1,.05,.2],['Orbit inclination (degrees)',0,90,5,60]],'Projected sky x (mas)','Projected sky y (mas)',([m,l,i])=>{const shape=(a,n)=>({name:n,points:grid(0,2*pi,240).map(t=>[100*a*Math.cos(t),100*a*Math.cos(rad(i))*Math.sin(t)])});return{curves:[shape(-m,'Primary'),shape(1-m,'Companion'),shape(l-m,'Photocentre')],result:'A 1 au relative orbit at 10 pc spans 100 mas. Photocentre semimajor axis '+f(100*Math.abs(l-m))+' mas; it vanishes when mass and light fractions agree.'};});
add('orbital-dwell',[['Orbital eccentricity',0,.85,.05,.6]],'True anomaly from periapsis (degrees)','Probability density per degree',([e])=>({curves:[C('Uniform sampling in time',grid(0,360,400),a=>(1-e*e)**1.5/(360*(1+e*Math.cos(rad(a)))**2))],result:'Apoapsis/periapsis sampling-density ratio '+f(((1+e)/(1-e))**2)+'. A time histogram is not uniform in orbital angle.'}));
add('kepler-clock',[['Perigee altitude above Earth (km)',250,3000,50,250],['Apogee radius from Earth centre (km)',20000,50000,1,42164]],'Orbital time (hours)','Distance from Earth centre (km)',([altitude,ra])=>{const rp=6378.137+altitude,a=(rp+ra)/2,e=(ra-rp)/(ra+rp),T=2*pi*Math.sqrt(a**3/398600.4418),x=grid(0,T,300);return{curves:[{name:'Analytical Kepler ellipse',points:x.map(t=>{const M=2*pi*t/T;let E=M;for(let i=0;i<12;i++)E-=(E-e*Math.sin(E)-M)/(1-e*Math.cos(E));return[t/3600,a*(1-e*Math.cos(E))];})}],result:'Period '+T.toFixed(2)+' s ('+f(T/3600)+' hours); eccentricity '+f(e)+'. Perigee/apogee radii '+rp.toFixed(3)+' / '+ra+' km. Analytical central-gravity reference with Earth radius 6378.137 km and μ = 398600.4418 km³/s²; the OneSimulation notebook separately checks integration and crossing-time errors.'};});
add('coax',[['Relative permittivity',1,6,.25,2.25],['Inner-conductor centre offset (mm)',0,.9,.025,0]],'Inner-conductor centre offset (mm)','TEM characteristic impedance (Ω)',([e,d])=>{const a=.45,b=1.475,e0=8.8541878128e-12,mu0=1.25663706212e-6,g=x=>Math.acosh((b*b+a*a-x*x)/(2*a*b)),cap=x=>2*pi*e0*e/g(x),ind=x=>mu0*g(x)/(2*pi),z=x=>Math.sqrt(ind(x)/cap(x));return{curves:[C('Eccentric cylindrical cable',grid(0,.9),z),P('Chosen geometry',d,z(d))],result:'C = '+f(cap(d)*1e12)+' pF/m; L = '+f(ind(d)*1e9)+' nH/m; Z₀ = '+f(z(d))+' Ω. Exact TEM reference for the notebook geometry a = 0.450 mm, b = 1.475 mm; uniform nonmagnetic dielectric, lossless circular conductors. The OneSimulation charge/energy estimates include mesh error.'};});
add('coupled-blocks',[['Heat capacity C₁ (J/K)',100,2000,50,500],['Heat capacity C₂ (J/K)',100,2500,50,1500],['Thermal conductance G (W/K)',.5,10,.25,2]],'Time (s)','Temperature (K)',([c1,c2,G])=>{const mean=(360*c1+300*c2)/(c1+c2),tau=c1*c2/(G*(c1+c2)),x=grid(0,5*tau),ds=c1*Math.log(mean/360)+c2*Math.log(mean/300);return{curves:[C('Initially hot block',x,t=>mean+(360-mean)*Math.exp(-t/tau)),C('Initially cold block',x,t=>mean+(300-mean)*Math.exp(-t/tau)),C('Energy-weighted equilibrium',x,()=>mean)],result:'Equilibrium '+f(mean)+' K; relaxation time '+f(tau)+' s; decay rate '+f(1/tau)+' s⁻¹; total entropy increase '+f(ds)+' J/K. Exact solution of the notebook’s isolated two-block ODE, starting at 360 K and 300 K with constant heat capacities and conductance.'};});
add('polygon-scale',[['Uniform length scale (nm)',.5,2,.01,1],['Particle mass / electron mass',1,3,.1,1]],'Uniform length scale (nm)','Ground energy (eV)',([length,mass])=>{const energy=(l,m)=>.09669586/(m*l*l);return{curves:[C('Chosen uniform effective mass',grid(.5,2),l=>energy(l,mass)),C('Electron mass',grid(.5,2),l=>energy(l,1)),P('Chosen device',length,energy(length,mass))],result:'Ground energy '+f(energy(length,mass))+' eV. All levels scale by '+f(1/(mass*length*length))+' relative to the recorded 1 nm, electron-mass polygon. The plotted baseline 0.09669586 eV is the recorded OneSimulation polygon-A ground energy; this algebraic rescaling preserves its shape and hard-wall condition and does not re-solve the 2D mesh.'};});
add('photonic-gap',[['Second-layer relative permittivity',1,13,.25,13],['Physical period a (mm)',.5,2,.1,1]],'Reduced frequency fa/c','Transfer-matrix half trace = cos(qa)',([e2,a])=>{const n1=Math.sqrt(13),n2=Math.sqrt(e2),centre=1/(n1+n2),H=v=>Math.cos(pi*v*n1)*Math.cos(pi*v*n2)-.5*(n1/n2+n2/n1)*Math.sin(pi*v*n1)*Math.sin(pi*v*n2),lo=e2===13?centre:bisect(v=>H(v)+1,0,centre),hi=e2===13?centre:bisect(v=>H(v)+1,centre,2*centre),x=grid(0,.42,500);return{curves:[C('Equal physical layer widths a/2',x,H),C('Upper propagating limit',x,()=>1),C('Lower propagating limit',x,()=>-1),P('First zone-edge mode',lo,-1),P('Second zone-edge mode',hi,-1)],result:'Zone-edge frequencies fa/c = '+lo.toFixed(5)+' and '+hi.toFixed(5)+'; gap / midgap '+(200*(hi-lo)/(hi+lo)).toFixed(3)+'%. Physical edges '+f(lo*299792458/a/1e6)+' and '+f(hi*299792458/a/1e6)+' GHz. Exact transfer matrix for ε₁ = 13 and equal half-period layers, matching the OneSimulation Bloch cell; |half trace| > 1 is a gap. Scaling the period changes physical frequency but not these reduced curves.'};});
add('plane-image',[['Charge height (cm)',.5,5,.25,2],['Point charge (nC)',1,10,1,1]],'Lateral position on grounded plane (cm)','Induced surface charge (µC/m²)',([h,q])=>({curves:[C('Image-charge surface density',grid(-10,10,400),x=>-q*1e-9*(h/100)/(2*pi*((x/100)**2+(h/100)**2)**1.5)*1e6)],result:'The profile is a radial cut through the two-dimensional surface density. Integrating over the entire plane gives −q; integrating this line alone does not.'}));
add('boundary-harmonics',[['Spatial harmonic number',1,6,1,1],['Selected probe height / fundamental period',0,1,.05,.5]],'Probe height / fundamental period','Potential amplitude / surface amplitude',([n,h])=>({curves:[C('Fundamental',grid(0,1),y=>Math.exp(-2*pi*y)),C('Selected spatial harmonic',grid(0,1),y=>Math.exp(-2*pi*n*y)),P('Selected probe',h,Math.exp(-2*pi*n*h))],result:'Amplitude at the probe '+f(Math.exp(-2*pi*n*h))+'. Recovering the boundary coefficient multiplies amplitude errors by '+f(Math.exp(2*pi*n*h))+'.'}));
add('dep-contrast',[['Particle conductivity (S/m)',.001,.2,.001,.02],['Medium conductivity (S/m)',.001,.2,.001,.1]],'log10 frequency (Hz)','Complex dipole contrast',([sp,sm])=>{const ep=3*8.8541878128e-12,em=80*8.8541878128e-12,K=x=>{const w=2*pi*10**x;return cdiv([sp-sm,w*(ep-em)],[sp+2*sm,w*(ep+2*em)]);};return{curves:[C('Real contrast',grid(3,10),x=>K(x)[0]),C('Imaginary contrast',grid(3,10),x=>K(x)[1])],result:'Particle/medium relative permittivities are 3/80. The sign of the real contrast controls the time-averaged force in a field-intensity gradient; a zero crossing need not remove dielectric loss.'};});
add('magnetic-sheet',[['Frequency (kHz)',1,100,1,10],['Sheet half-thickness (mm)',.2,2,.1,1]],'Position across sheet (mm)','Field amplitude / imposed surface amplitude',([freq,a])=>{const delta=Math.sqrt(2/(2*pi*freq*1000*4*pi*1e-7*5.8e7))*1000,mag=x=>Math.sqrt((Math.cosh(2*x/delta)+Math.cos(2*x/delta))/(Math.cosh(2*a/delta)+Math.cos(2*a/delta)));return{curves:[C('Two faces driven in phase',grid(-a,a,300),mag)],result:'Copper conductivity 5.8×10⁷ S/m; skin depth '+f(delta)+' mm. Centre/surface amplitude '+f(mag(0))+'. The notebook solves the complex diffusion boundary-value problem independently.'};});
add('waveguide-speeds',[['Selected frequency / cutoff',1.05,4,.05,2]],'Frequency / cutoff','Speed / medium wave speed',([r])=>({curves:[C('Group velocity',grid(1.05,4),x=>Math.sqrt(1-1/x**2)),C('Phase velocity',grid(1.05,4),x=>1/Math.sqrt(1-1/x**2)),P('Selected group speed',r,Math.sqrt(1-1/r**2))],result:'Group × phase speed = medium wave speed squared. At the selected frequency the group ratio is '+f(Math.sqrt(1-1/r**2))+'. Phase velocity exceeding c carries no superluminal information.'}));
add('reflection',[['Load / line impedance',.1,5,.1,2]],'Load / line impedance','Voltage coefficient or reflected power fraction',([r])=>{const g=x=>(x-1)/(x+1);return{curves:[C('Voltage reflection Γ',grid(.1,5),g),C('Reflected power Γ²',grid(.1,5),x=>g(x)**2),P('Selected voltage reflection',r,g(r))],result:'Voltage reflection '+f(g(r))+'; reflected power fraction '+f(g(r)**2)+'. Loads r and 1/r give opposite voltage signs and equal reflected power.'};});
add('refrigeration',[['Discharge enthalpy h2 (kJ/kg)',425,460,1,430],['Liquid subcooling (K)',0,20,1,0]],'Liquid subcooling (K)','Refrigeration COP',([h2,d])=>{const h1=392.66,h3=241.72,cp=1.45,cop=x=>(h1-h3+cp*x)/(h2-h1);return{curves:[C('Four-state enthalpy balance',grid(0,20),cop),P('Selected subcooling',d,cop(d))],result:'At selected states: cooling '+f(h1-h3+cp*d)+' kJ/kg, work '+f(h2-h1)+' kJ/kg, valve vapour fraction '+f((h3-cp*d-186.70)/(h1-186.70))+'. Saturated endpoint data are held fixed; liquid cp=1.45 kJ/(kg K) is an illustrative local approximation.'};});
// Sixteen-point Gauss quadrature resolves the finite slit aperture throughout the control range.
function slitQuadrature(){const nodes=[];for(let j=1;j<=8;j++){let z=Math.cos(pi*(j-.25)/16.5),derivative;for(let it=0;it<12;it++){let p0=1,p1=z;for(let n=2;n<=16;n++){const p=((2*n-1)*z*p1-(n-1)*p0)/n;p0=p1;p1=p;}derivative=16*(z*p1-p0)/(z*z-1);const dz=p1/derivative;z-=dz;if(Math.abs(dz)<1e-15)break;}const weight=2/((1-z*z)*derivative*derivative);nodes.push([z,weight],[-z,weight]);}return nodes;}
const slitNodes=slitQuadrature();
// Conjugate outgoing H₀ asymptotics. Here kr ≥ 17.17; ten terms give < 10⁻¹¹ absolute error.
function slitHankel(x){let re=1,im=0,tr=1,ti=0;for(let m=1;m<=10;m++){const q=(2*m-1)**2/(8*m*x),nr=-ti*q;ti=tr*q;tr=nr;re+=tr;im+=ti;}const phase=x-pi/4,s=Math.sqrt(2/(pi*x));return[s*(re*Math.cos(phase)+im*Math.sin(phase)),s*(im*Math.cos(phase)-re*Math.sin(phase))];}
add('finite-slits',[['Slit separation / wavelength',2,4,.05,3],['Receiver radius (m)',.6,1.5,.05,.9],['Slit width (m)',.02,.08,.005,.05]],'Receiver angle from broadside (degrees)','Normalised pressure amplitude',([ratio,R,width])=>{const d=.3,k=2*pi*ratio/d,pressure=a=>{const X=R*Math.sin(rad(a)),Y=R*Math.cos(rad(a));let re=0,im=0;for(const centre of [-d/2,d/2])for(const [u,w] of slitNodes){const h=slitHankel(k*Math.hypot(X-centre-width*u/2,Y));re+=w*h[0];im+=w*h[1];}return Math.hypot(re,im);},norm=pressure(0),x=grid(-90,90,720),points=x.map(a=>[a,pressure(a)/norm]),mins=[];for(let j=361;j<points.length-1;j++)if(points[j][1]<points[j-1][1]&&points[j][1]<points[j+1][1])mins.push(points[j][0]);return{curves:[{name:'Finite-radius Rayleigh aperture integral',points},C('Fraunhofer far-field limit',x,a=>Math.abs(Math.cos(pi*ratio*Math.sin(rad(a)))*sinc(pi*ratio*width/d*Math.sin(rad(a)))))],result:'Frequency '+f(ratio*343/d)+' Hz; spacing 0.30 m; sound speed 343 m/s. First two sampled minima '+mins.slice(0,2).map(a=>a.toFixed(2)+'°').join(', ')+' (0.25° sampling). This is the notebook’s 2D Hankel Rayleigh reference with uniform slit velocity; the full OneSimulation guide/screen solution also resolves edge-dependent aperture velocity.'};});
// Worked derivations often ask a different quantitative question from the chapter figure.
add('inelastic-carts',[['Target / incident mass',.2,3,.1,.7],['Restitution coefficient',0,1,.05,.6],['Initial relative speed (m/s)',.2,3,.1,1.5]],'Restitution coefficient','Energy fraction of initial relative motion',([r,e,u])=>({curves:[C('Remaining relative energy',grid(0,1),x=>x*x),C('Dissipated relative energy',grid(0,1),x=>1-x*x),P('Selected restitution',e,e*e)],result:'For incident mass 0.6 kg and target mass 0.6r kg, contact impulse = '+f(.6*r/(1+r)*(1+e)*u)+' N s. Relative-energy loss fraction '+f(1-e*e)+'. A common laboratory velocity shift leaves impulse and this loss unchanged.'}));
add('saddle-transit',[['Mass (kg)',.05,.5,.01,.2],['Barrier curvature (N/m)',1,10,.5,5],['Track half-length (mm)',10,80,5,40]],'Energy excess (mJ)','Barrier-crossing time (s)',([m,k,L])=>({curves:[C('Exact quadratic summit',grid(.005,1,350),e=>2*Math.sqrt(m/k)*Math.asinh(L/1000*Math.sqrt(k/(2*e/1000)))),C('Near-threshold logarithm',grid(.005,1,350),e=>Math.sqrt(m/k)*Math.log(2*k*(L/1000)**2/(e/1000)))],result:'The crossing slows logarithmically as excess energy tends to zero. At 0.1 mJ the exact time is '+f(2*Math.sqrt(m/k)*Math.asinh(L/1000*Math.sqrt(k/.0002)))+' s. The quadratic potential must remain accurate on this interval.'}));
add('pulley',[['Descending load M (kg)',.6,2,.1,1.2],['Pulley rotational equivalent 4I/R² (kg)',0,1,.05,.4]],'Counterweight m (kg)','Signed load acceleration (m/s²)',([M,J])=>({curves:[C('Constrained pulley mechanism',grid(.1,1.2),m=>9.81*(M-2*m)/(M+4*m+J))],result:'The counterweight moves twice as far with opposite sign. Driving mass M−2m and effective inertia M+4m+4I/R² explain the reversal at m=M/2.'}));
add('two-cart-modes',[['Light cart mass (kg)',.1,.5,.05,.25],['Spring stiffness (N/m)',10,60,5,25],['Heavy/light initial displacement ratio',-.5,1.5,.05,0]],'Time (s)','Cart displacement (mm)',([m,k,b])=>{const l=(3-Math.sqrt(3))/2,h=(3+Math.sqrt(3))/2,r1=2-l,r2=2-h,a=4,c1=(4*b-r2*a)/(r1-r2),c2=a-c1;return{curves:[C('Light cart',grid(0,5,600),t=>c1*Math.cos(Math.sqrt(k/m*l)*t)+c2*Math.cos(Math.sqrt(k/m*h)*t)),C('Heavy cart (mass 2m)',grid(0,5,600),t=>r1*c1*Math.cos(Math.sqrt(k/m*l)*t)+r2*c2*Math.cos(Math.sqrt(k/m*h)*t))],result:'Modal frequencies '+f(Math.sqrt(k/m*l))+' and '+f(Math.sqrt(k/m*h))+' rad/s. Pure-mode displacement ratios '+f(r1)+' and '+f(r2)+'. Released from rest; equal adjacent springs and fixed outer ends.'};});
add('coriolis-drop',[['Latitude (degrees)',-80,80,1,48]],'Drop height (m)','Eastward offset (mm)',([a])=>({curves:[C('Leading Coriolis offset',grid(1,100),h=>7.292115e-5*Math.cos(rad(a))*9.81/3*(2*h/9.81)**1.5*1000)],result:'Flight time is √(2h/g). The offset scales as h^(3/2), assumes release from rest relative to the tower, and neglects drag and higher rotation orders.'}));
add('phase-area',[['Scaled step ωΔt',.02,.4,.02,.2]],'Number of time steps','Phase-space area / initial area',([h])=>({curves:[C('Explicit Euler',grid(0,100,100),n=>(1+h*h)**n),C('Exact Hamiltonian flow',grid(0,100,100),()=>1),C('Symplectic Euler',grid(0,100,100),()=>1)],result:'Euler determinant 1+(ωΔt)² = '+f(1+h*h)+'. A symplectic scheme preserves area but still needs a step-convergence check for phase accuracy.'}));
add('kepler-timing',[['Orbital eccentricity',0,.85,.05,.6],['Orbital period (years)',1,12,.5,8]],'Eccentric anomaly (degrees)','Time since periapsis (years)',([e,P0])=>({curves:[C('Kepler clock',grid(0,360),a=>P0*(rad(a)-e*Math.sin(rad(a)))/(2*pi)),C('Uniform geometric parameter',grid(0,360),a=>P0*a/360)],result:'At the upper semiminor-axis endpoint: '+f(P0*(pi/2-e)/(2*pi))+' years. Geometry and elapsed time are related by M=E−e sin E.'}));
add('momentum-cross-section',[['Angular asymmetry α',-1,1,.05,.6]],'Scattering angle (degrees)','Contribution per radian / total cross-section',([a])=>({curves:[C('Event-count density',grid(0,180),t=>.5*(1+a*Math.cos(rad(t)))*Math.sin(rad(t))),C('Momentum-transfer density',grid(0,180),t=>.5*(1-Math.cos(rad(t)))*(1+a*Math.cos(rad(t)))*Math.sin(rad(t)))],result:'Transport / total cross-section = 1−α/3 = '+f(1-a/3)+'. Equal event counts can transfer unequal momentum.'}));
add('power-bandwidth',[['Mass (kg)',.1,.8,.05,.4],['Stiffness (N/m)',40,240,10,160],['Damping (N s/m)',1,10,.5,4]],'Drive angular frequency (rad/s)','Mean absorbed power for 2 N peak drive (W)',([m,k,c])=>{const D=Math.sqrt(c*c+4*m*k);return{curves:[C('Absorbed power',grid(0,80,500),w=>2*c*w*w/((k-m*w*w)**2+c*c*w*w))],result:'Half-power edges '+f((D-c)/(2*m))+' and '+f((D+c)/(2*m))+' rad/s; bandwidth c/m = '+f(c/m)+'. Peak power 2/c = '+f(2/c)+' W.'};});
add('duffing-harmonic',[['Amplitude (mm)',2,20,1,12],['Cubic stiffness (N/m³)',1000,20000,1000,10000]],'Amplitude (mm)','Third-harmonic displacement (µm)',([A,b])=>({curves:[C('First perturbative harmonic',grid(0,20),a=>1000*a*(b*(a/1000)**2/20)/32)],result:'Linear stiffness 20 N/m. At chosen amplitude ε='+f(b*(A/1000)**2/20)+', third harmonic '+f(1000*A*b*(A/1000)**2/(20*32))+' µm; first frequency shift '+f(100*3*b*(A/1000)**2/(8*20))+'%. Requires ε≪1.'}));
add('debye-waller',[['Projected variance increase (nm²)',.00002,.0003,.00001,.00009]],'Scattering wavevector Q (nm⁻¹)','Corrected intensity / initial intensity',([v])=>({curves:[C('Gaussian displacement attenuation',grid(0,100),q=>Math.exp(-q*q*v))],result:'Intensity ratio is exp(−Q²Δ⟨u²⟩). Doubling Q quadruples the attenuation exponent for the same projected displacement distribution.'}));
add('chain-count',[['Selected fraction of band-edge frequency',.05,.95,.01,.9]],'Frequency / band edge','Fraction of longitudinal chain modes below frequency',([x])=>({curves:[C('Uniform wavevector count',grid(0,1),q=>2/pi*Math.asin(q)),P('Selected cutoff',x,2/pi*Math.asin(x))],result:'Fraction above selected cutoff '+f(1-2/pi*Math.asin(x))+'. The spectral median is ωmax/√2; mode density diverges integrably at the band edge.'}));
add('fermi-pressure',[['Initial pressure (kPa)',1,30,1,12]],'Volume / initial volume','Degenerate-gas pressure (kPa)',([p])=>({curves:[C('Zero-temperature 3D ideal Fermi gas',grid(.3,2),v=>p/v**(5/3))],result:'At fixed particle number P∝V^(−5/3), and the bulk modulus is 5P/3. Nonrelativistic, noninteracting fermions; thermal corrections omitted.'}));
add('mass-tensor',[['Principal mass mx/me',.1,1,.05,.2],['Principal mass my/me',.1,1,.05,.8]],'Force angle from x axis (degrees)','Acceleration / (force divided by electron mass)',([mx,my])=>({curves:[C('Parallel acceleration',grid(0,90),a=>Math.cos(rad(a))**2/mx+Math.sin(rad(a))**2/my),C('Transverse acceleration',grid(0,90),a=>Math.sin(rad(a))*Math.cos(rad(a))*(1/my-1/mx))],result:'Acceleration need not align with force. The longitudinal inverse mass is cos²θ/mx + sin²θ/my.'}));
add('diffusion-recombination',[['Diffusivity (cm²/s)',2,30,1,12],['Minority lifetime (µs)',.5,8,.5,3]],'Distance from illuminated edge (µm)','Excess minority density / boundary value',([D,t])=>{const L=Math.sqrt(D*t*1e-6)*1e4;return{curves:[C('Steady diffusion with recombination',grid(0,300),x=>Math.exp(-x/L))],result:'Diffusion length '+f(L)+' µm. The surface flux / boundary density equals D/L = '+f(D/(L/1e4))+' cm/s. Constant diffusivity, low injection, semi-infinite sample.'};});
add('homogenised-stack',[['High-index layer fraction',.05,.95,.05,.25],['High refractive index',1.6,3.5,.1,2]],'High-index layer fraction','Long-wavelength effective index',([p,n])=>({curves:[C('Normal-incidence dielectric stack',grid(0,1),x=>Math.sqrt(x*n*n+(1-x)*1.5**2)),P('Selected fraction',p,Math.sqrt(p*n*n+(1-p)*1.5**2))],result:'Low index is 1.5. The squared indices, rather than indices, average in this long-wavelength transverse-field limit. The cell must be much shorter than the wavelength.'}));
add('drude',[['Collision time (fs)',10,300,10,40]],'Frequency (THz)','Conductivity / DC conductivity',([t])=>({curves:[C('Dissipative real part',grid(0,5),f=>1/(1+(2*pi*f*t/1000)**2)),C('Reactive imaginary part',grid(0,5),f=>(2*pi*f*t/1000)/(1+(2*pi*f*t/1000)**2))],result:'Imaginary/real ratio equals ωτ. Heating uses the real conductivity and half the squared peak electric field.'}));
add('cyclotron-mass',[['Principal mass mx/me',.05,1,.05,.1],['Principal mass my/me',.05,1,.05,.9]],'Magnetic induction (T)','Cyclotron frequency (GHz)',([x,y])=>({curves:[C('Elliptical parabolic pocket',grid(0,3),B=>27.99249*B/Math.sqrt(x*y))],result:'Cyclotron mass / me = √(mx my) = '+f(Math.sqrt(x*y))+'. This geometric mean differs from the longitudinal effective mass.'}));
add('spin-magnetisation',[['Spin quantum number J',.5,3,.5,1],['Temperature (K)',2,40,1,10]],'Magnetic induction (T)','Magnetic moment per ion (Bohr magnetons)',([J,T])=>{const moment=B=>{let z=0,m=0;for(let j=-J;j<=J+.01;j++){const w=Math.exp(2*.671713815*B*(j-J)/T);z+=w;m+=2*j*w;}return m/z;};return{curves:[C('Exact spin partition sum, g=2',grid(0,15),moment)],result:'Saturation moment 2J='+f(2*J)+' μB; Curie effective moment 2√(J(J+1))='+f(2*Math.sqrt(J*(J+1)))+' μB. Independent local moments.'};});
add('bcs-weights',[['Gap (meV)',.2,6,.2,4],['Normal-state energy ξ (meV)',-8,8,.2,3]],'Normal-state energy ξ (meV)','Electron spectral weight',([d,xi])=>{const u=x=>(1+x/Math.hypot(x,d))/2;return{curves:[C('Positive-energy electron weight u²',grid(-8,8),u),C('Negative-energy electron weight v²',grid(-8,8),x=>1-u(x)),P('Selected positive peak',xi,u(xi))],result:'Peak energies ±'+f(Math.hypot(xi,d))+' meV; weights sum to one. The measured electron spectrum also needs occupation and instrumental factors.'};});
add('graded-charge',[['Sphere radius (mm)',20,100,5,60],['Total charge (nC)',.1,2,.1,.2]],'Radius / sphere radius','Radial electric field (V/m)',([R,Q])=>{const scale=8.9875517923e9*Q*1e-9/(R/1000)**2;return{curves:[C('Linearly falling volume-charge density',grid(0,2),x=>scale*(x<=1?4*x-3*x*x:1/(x*x)))],result:'Field maximum at r=2R/3 = '+f(2*R/3)+' mm. Surface/centre potentials '+f(scale*R/1000)+' / '+f(2*scale*R/1000)+' V. Density is proportional to 1−r/R inside.'};});
add('sphere-force',[['Sphere radius (mm)',20,80,5,50],['External charge (nC)',.5,5,.5,2]],'Charge distance / sphere radius','Attractive force magnitude (µN)',([R,q])=>({curves:[C('Grounded conducting sphere',grid(1.2,5,300),x=>8.9875517923e9*(q*1e-9)**2*x/((R/1000)**2*(x*x-1)**2)*1e6)],result:'Image charge q′=−q/(a/R); force acts towards the sphere. At a=2R the image lies at R/2 and carries −q/2.'}));
add('differential-inductance',[['Differential relative permeability',50,1000,25,200],['Core length (mm)',50,200,10,100]],'Air-gap length (mm)','Incremental inductance (mH)',([mu,l])=>({curves:[C('Incremental magnetic circuit',grid(.05,2),g=>4*pi*1e-7*100**2*100e-6/(l/1000/mu+g/1000)*1000)],result:'N=100 turns and A=100 mm². Differential permeability is the local slope dB/dH at the bias; substituting a secant B/H gives a different inductance.'}));
add('generator',[['Angular speed (rad/s)',20,200,10,100],['Coil inductance (mH)',5,100,5,40]],'Rotor phase (degrees)','Voltage (V) or current (A)',([w,L])=>{const R=3,E=.04*w,Z=Math.hypot(R,w*L/1000),lag=Math.atan2(w*L/1000,R);return{curves:[C('Generated EMF (V)',grid(0,360),a=>E*Math.sin(rad(a))),C('Winding current (A)',grid(0,360),a=>E/Z*Math.sin(rad(a)-lag))],result:'NAB=0.04 Wb, R=3 Ω. Phase lag '+f(lag*180/pi)+'°; mean shaft power '+f(.5*R*(E/Z)**2)+' W and mean torque '+f(.5*R*(E/Z)**2/w)+' N m. Voltage and current curves carry separately named units.'};});
add('capacitor-flux',[['Voltage (V)',2,30,1,10],['Voltage ramp (V/µs)',-5,5,.25,2],['Plate gap (mm)',.5,3,.25,1]],'Radial position (mm)','Signed inward Poynting flux (W/m²)',([V,dV,g])=>({curves:[C('Inward energy flux',grid(0,40),r=>(V/(g/1000))*8.8541878128e-12*(r/1000)/2*(dV*1e6/(g/1000)))],result:'40 mm plate radius. Electrical input VI = '+f(V*8.8541878128e-12*pi*.04**2/(g/1000)*dV*1e6)+' W. A negative ramp reverses energy flow at fixed positive voltage.'}));
add('multipole-origin',[['Second / first charge ratio',.1,2,.1,.5],['Charge separation (mm)',5,50,5,30]],'Probe distance from first charge (m)','Potential (V) for first charge 2 nC',([r,d])=>{const q1=2e-9,q2=r*q1,a=d/1000*q2/(q1+q2),x=grid(.1,1.2);return{curves:[C('Two exact point charges',x,x=>8.9875517923e9*(q1/x+q2/(x-d/1000))),C('Monopole at centre of charge',x,x=>8.9875517923e9*(q1+q2)/(x-a)),C('Monopole + dipole at old origin',x,x=>8.9875517923e9*((q1+q2)/x+q2*d/1000/x**2))],result:'Centre of charge '+f(1000*a)+' mm. Shifting the expansion origin removes the dipole for nonzero total charge; the exact field stays unchanged.'};});
add('dielectric-pore',[['Host relative permittivity',1,8,.25,4]],'Inclusion relative permittivity','Internal / applied electric field',([h])=>({curves:[C('Spherical inclusion in dielectric host',grid(1,12),c=>3*h/(c+2*h))],result:'An air pore has field ratio '+f(3*h/(1+2*h))+'. The formula depends on both host and inclusion, with continuous potential and normal displacement.'}));
const erf=x=>{const sign=Math.sign(x),a=Math.abs(x),t=1/(1+.3275911*a);return sign*(1-(((((1.061405429*t-1.453152027)*t)+1.421413741)*t-.284496736)*t+.254829592)*t*Math.exp(-a*a));};
add('magnetic-step',[['Time after switching (ms)',.02,1,.02,.2],['Conductivity (MS/m)',10,60,5,60]],'Depth into conductor (mm)','Induction / imposed surface induction',([t,s])=>{const D=1/(4*pi*1e-7*s*1e6);return{curves:[C('Diffusion of a step field',grid(0,5),x=>1-erf((x/1000)/(2*Math.sqrt(D*t/1000))))],result:'D = '+f(D)+' m²/s; half-amplitude depth '+f(2*.476936276*Math.sqrt(D*t/1000)*1000)+' mm. Nonmagnetic uniform half-space with a suddenly imposed surface field.'};});
add('below-cutoff',[['Frequency / cutoff',.2,.95,.05,.8],['Guide width (mm)',10,50,2,20]],'Distance along guide (mm)','Relative field or intensity',([r,a])=>{const alpha=pi/(a/1000)*Math.sqrt(1-r*r);return{curves:[C('Field amplitude',grid(0,100),z=>Math.exp(-alpha*z/1000)),C('Squared-amplitude detector response',grid(0,100),z=>Math.exp(-2*alpha*z/1000))],result:'Decay constant '+f(alpha)+' m⁻¹. An isolated evanescent mode carries no propagating axial power; the squared amplitude describes a local probe response.'};});
add('line-steps',[['Source / line resistance',.2,3,.1,1],['Load / line resistance',.2,5,.1,2]],'Time / one-way transit time','Load voltage / source voltage',([s,r])=>{const gl=(r-1)/(r+1),gs=(s-1)/(s+1),v=1/(1+s),points=[[0,0]];let y=0;for(let n=0;n<12;n++){const t=2*n+1;points.push([t,y]);y+=(1+gl)*v*(gl*gs)**n;points.push([t,y]);}return{curves:[{name:'Successive load arrivals',points},C('DC limit',grid(0,23,1),()=>r/(s+r))],result:'ΓL='+f(gl)+', Γs='+f(gs)+'. Each returning increment is multiplied by ΓLΓs; the final load voltage is RL/(Rs+RL).'};});
add('dielectric-force',[['Relative dielectric permittivity',2,6,.25,3],['Initial capacitor voltage (V)',100,1000,50,500]],'Inserted fraction of plate length','Force / initial force',([e,V])=>({curves:[C('Fixed voltage',grid(0,1),()=>1),C('Fixed charge initially at same V',grid(0,1),x=>1/(1+(e-1)*x)**2)],result:'For 20 mm plate width and 1 mm gap the initial force is '+f(.5*V*V*8.8541878128e-12*.02/.001*(e-1)*1e6)+' µN. Battery work must be included in the fixed-voltage balance.'}));
add('barrier-transmission',[['Barrier height / incident energy',.2,3,.05,2]],'Barrier thickness × incident wave number','Transmitted flux fraction',([r])=>{const T=x=>Math.abs(r-1)<1e-10?1/(1+x*x/4):r>1?1/(1+r*r/(4*(r-1))*Math.sinh(x*Math.sqrt(r-1))**2):1/(1+r*r/(4*(1-r))*Math.sin(x*Math.sqrt(1-r))**2);return{curves:[C('Exact rectangular barrier',grid(0,8,500),T)],result:'At threshold V0=E the limiting formula is 1/[1+(kL)²/4]. Below threshold repeated internal reflections give resonances; above it an evanescent region suppresses transmission.'};});
add('oscillator-uncertainty',[['Occupation number n',0,12,1,2]],'Occupation number n','Uncertainty in natural units',([n])=>({curves:[C('Δx / x0 and Δp / p0',grid(0,12,12),j=>Math.sqrt(2*j+1)),C('ΔxΔp / ℏ',grid(0,12,12),j=>j+.5),P('Selected uncertainty product',n,n+.5)],result:'x0=√[ℏ/(2mω)] and p0=√[mℏω/2]. The n=0 state saturates the lower bound; number-state uncertainty grows with n.'}));
add('level-population',[['Coupling g (meV)',.1,1,.05,.3]],'Detuning Δ (meV)','Positive bare-state population in lower eigenstate',([g])=>({curves:[C('Lower-level bare-state weight',grid(-3,3),d=>(1-d/Math.hypot(d,2*g))/2)],result:'Hellmann–Feynman: ∂E−/∂Δ = P+−1/2. Population determines the measured energy slope even when a small-perturbation expansion fails.'}));
add('singlet',[['Analyser angle (degrees)',0,180,5,60],['Independent pairs recorded',100,2000,100,1200]],'Joint outcome index (0=++, 1=+−, 2=−+, 3=−−)','Expected pair counts',([a,N])=>{const c=Math.cos(rad(a));return{curves:[{name:'Spin singlet',points:[[0,N*(1-c)/4],[1,N*(1+c)/4],[2,N*(1+c)/4],[3,N*(1-c)/4]]}],result:'Each single-analyser marginal is one half; joint correlation = −cosθ = '+f(-c)+'. Compare rotated analysers to distinguish the singlet from an incoherent anti-aligned mixture.'};});
add('overlap-eigen',[['Orbital overlap s',0,.8,.05,.25],['Energy-reference shift C (eV)',-2,3,.25,0]],'Orbital overlap s','Variational energy (eV)',([s,C0])=>({curves:[C('Symmetric generalised eigenstate',grid(0,.8),x=>2.5/(1+x)+C0),C('Antisymmetric generalised eigenstate',grid(0,.8),x=>3.5/(1-x)+C0),P('Selected symmetric energy',s,2.5/(1+s)+C0)],result:'Unshifted H diagonals 3 eV and off-diagonal −0.5 eV. An energy shift is H→H+CS, so both generalised eigenvalues shift by exactly C.'}));
add('power-law-spacing',[['Potential exponent p in |x|^p',1,6,1,4]],'Energy / reference energy','Period or local spacing / reference',([p])=>({curves:[C('Classical period',grid(.2,5),E=>E**(1/p-.5)),C('Semiclassical spacing',grid(.2,5),E=>E**(.5-1/p))],result:'The action scales as E^(1/2+1/p). Differentiation gives T∝E^(1/p−1/2) and ΔE≈h/T. This local-spacing estimate improves for high quantum numbers.'}));
add('exchange-contact',[['Contact strength g (meV µm)',.5,4,.25,2],['Density overlap D (1/µm)',.02,.3,.01,.12]],'Orbital overlap magnitude |S|','First-order contact shift (meV)',([g,D])=>({curves:[C('Symmetric spatial state',grid(0,1),s=>2*g*D/(1+s*s)),C('Antisymmetric spatial state',grid(0,.99),()=>0)],result:'The antisymmetric wavefunction vanishes at coincidence. Its state is undefined when the two orbitals become identical; the symmetric S=1 limit is well defined.'}));
add('static-echo',[['Rms cyclic detuning (kHz)',.2,3,.1,1],['Refocusing pulse time τ (ms)',.1,2,.05,.25],['Homogeneous T2 (ms)',2,20,1,10]],'Readout time (ms)','Coherence magnitude',([s,tau,T2])=>({curves:[C('Free induction',grid(0,4,500),t=>Math.exp(-.5*(2*pi*s*t)**2-t/T2)),C('Single ideal refocusing pulse',grid(0,4,500),t=>Math.exp(-.5*(2*pi*s*(t<tau?t:2*tau-t))**2-t/T2))],result:'Echo centre at t=2τ='+f(2*tau)+' ms; its height exp(−2τ/T2)='+f(Math.exp(-2*tau/T2))+'. Static detuning reverses; homogeneous decay remains.'}));
add('weyl',[['Rectangle aspect ratio at fixed area',.5,3,.1,1]],'Wave number × √area / π','Number of positive-index Dirichlet modes',([r])=>{const exact=q=>{let N=0;for(let n=1;n<=Math.floor(q*Math.sqrt(r));n++)N+=Math.floor(Math.sqrt(Math.max(0,q*q-n*n/r))/Math.sqrt(r)+1e-10);return N;};return{curves:[C('Exact lattice count',grid(0,12,480),exact),C('Area term',grid(0,12),q=>pi*q*q/4),C('Area minus perimeter term',grid(0,12),q=>pi*q*q/4-(Math.sqrt(r)+1/Math.sqrt(r))*q/2)],result:'At KL/π=5 for a square: '+exact(5)+' modes. The perimeter correction is an asymptotic smoothed count, not an exact staircase at low frequency.'};});
add('sound-compressibility',[['Density (kg/m³)',.5,2,.1,1.2],['Heat-capacity ratio cp/cv',1,1.7,.05,1.4]],'Pressure (kPa)','Sound speed (m/s)',([rho,g])=>({curves:[C('Adiabatic response',grid(50,200),p=>Math.sqrt(g*p*1000/rho)),C('Isothermal response',grid(50,200),p=>Math.sqrt(p*1000/rho))],result:'For ideal gas κT=1/p, κs=κT/γ. At 100 kPa the speed is '+f(Math.sqrt(g*1e5/rho))+' m/s. A liquid instead requires measured compressibility.'}));
add('otto',[['Heat-capacity ratio γ',1.2,1.7,.05,1.4],['Compression ratio',2,12,.5,8]],'Compression ratio','Ideal Otto efficiency',([g,r])=>({curves:[C('Air-standard Otto cycle',grid(2,12),x=>1-x**(1-g)),P('Selected ratio',r,1-r**(1-g))],result:'Efficiency 1−r^(1−γ) = '+f(1-r**(1-g))+'. At initial 300 K, adiabatic compression reaches '+f(300*r**(g-1))+' K. Constant heat capacities and reversible adiabats are assumed.'}));
add('kelvin-droplet',[['Surface tension (N/m)',.02,.1,.002,.072],['Temperature (K)',280,360,5,300]],'Droplet radius (nm)','Equilibrium vapour pressure / flat-interface pressure',([g,T])=>({curves:[C('Kelvin curvature shift',grid(5,150),r=>Math.exp(2*g*18e-6/(8.314462618*T*r*1e-9)))],result:'Liquid molar volume fixed at 18 cm³/mol. Curvature raises the liquid chemical potential; molecular-scale droplets require corrections beyond this continuum model.'}));
add('finite-reservoir-variance',[['Partner / sample heat capacity',.1,10,.1,3]],'Partner / sample heat capacity','Energy rms / infinite-bath rms',([r])=>({curves:[C('Two finite thermal bodies',grid(.05,10),x=>Math.sqrt(x/(1+x))),P('Selected capacity ratio',r,Math.sqrt(r/(1+r)))],result:'Variance ratio CB/(CA+CB) = '+f(r/(1+r))+'. The canonical infinite-bath result is approached only when CB≫CA.'}));
add('trap-fluctuations',[['Temperature (K)',250,350,5,295],['Trap stiffness (µN/m)',.5,10,.25,2.5]],'Displacement (nm)','Equilibrium probability density (1/nm)',([T,k])=>{const s=Math.sqrt(1.380649e-23*T/(k*1e-6))*1e9;return{curves:[C('Harmonic equilibrium distribution',grid(-5*s,5*s,300),x=>Math.exp(-.5*(x/s)**2)/(Math.sqrt(2*pi)*s))],result:'Rms displacement '+f(s)+' nm; compliance 1/k = '+f(1/(k*1e-6))+' m/N. Variance = kBT × compliance.'};});
add('quantum-virial',[['Selected degeneracy nλ³/g',.005,.2,.005,.065]],'Degeneracy parameter nλ³/g','Pressure / classical ideal-gas pressure',([y])=>({curves:[C('Fermi leading correction',grid(0,.2),x=>1+x/2**2.5),C('Bose leading correction',grid(0,.2),x=>1-x/2**2.5),P('Selected Fermi gas',y,1+y/2**2.5)],result:'These are first quantum virial corrections, valid for nλ³/g≪1. Exchange raises the dilute fermion pressure and lowers the dilute boson pressure.'}));
add('diffusion-skin',[['Diffusivity (10⁻9 m²/s)',.2,5,.1,1.2],['Forcing period (s)',20,200,10,100]],'Depth (µm)','Concentration amplitude / surface amplitude',([D,P0])=>{const d=Math.sqrt(D*1e-9*P0/pi)*1e6;return{curves:[C('Oscillating boundary concentration',grid(0,600),x=>Math.exp(-x/d))],result:'Penetration depth '+f(d)+' µm; the phase lag is x/δ radians. Amplitude and phase supply independent checks of D.'};});
add('blackbody-peaks',[['Temperature (K)',300,2000,50,1200]],'Wavelength (µm)','Normalised spectral density (separate measures)',([T])=>{const a=14387.76877/T,lPeak=a/4.965114232,fPeak=a/2.821439372;const bl=l=>1/(l**5*Math.expm1(a/l)),bn=l=>1/(l**3*Math.expm1(a/l));return{curves:[C('Equal-wavelength channels',grid(.2,30,600),l=>bl(l)/bl(lPeak)),C('Equal-frequency channels, labelled by c/ν',grid(.2,30,600),l=>bn(l)/bn(fPeak))],result:'Wavelength-density peak '+f(lPeak)+' µm; frequency-density peak corresponds to '+f(fPeak)+' µm. The two densities use different channel widths and are not related by relabelling alone.'};});
add('debye-speed',[['Longitudinal speed (m/s)',3000,8000,250,6000],['Transverse speed (m/s)',1500,4500,250,3000]],'Transverse speed (m/s)','Effective Debye speed (m/s)',([L,T])=>{const vd=t=>(3/(1/L**3+2/t**3))**(1/3);return{curves:[C('Three acoustic polarisations',grid(1500,4500),vd),P('Selected material',T,vd(T))],result:'1/vD³=(1/vL³+2/vT³)/3. Longitudinal fraction of the low-temperature heat coefficient '+f((1/L**3)/(1/L**3+2/T**3))+'.'};});
add('vanthoff',[['Reaction enthalpy at 300 K (kJ/mol)',-30,30,2,-20],['Reaction heat-capacity difference (J/mol/K)',-100,200,10,100]],'Temperature (K)','Equilibrium constant',([H,Cp])=>({curves:[C('Integrated temperature-dependent enthalpy',grid(260,400),T=>4*Math.exp((H*1000-Cp*300)/8.314462618*(1/300-1/T)+Cp/8.314462618*Math.log(T/300)))],result:'K=4 at 300 K, ΔH(T)=ΔH(300)+ΔCp(T−300). Activities and standard states are held consistent.'}));
add('master-entropy',[['Forward rate (1/s)',.5,5,.25,3],['Reverse rate (1/s)',.5,5,.25,1],['Initial upper-state probability',.05,.95,.05,.25]],'Time (s)','Entropy production / kB (1/s)',([a,b,p0])=>{const eq=a/(a+b),p=t=>eq+(p0-eq)*Math.exp(-(a+b)*t);return{curves:[C('Two-state entropy production',grid(0,3),t=>{const x=p(t),fwd=a*(1-x),rev=b*x;return(fwd-rev)*Math.log(fwd/rev);})],result:'Equilibrium probability '+f(eq)+'; relaxation time '+f(1/(a+b))+' s. Production is nonnegative and vanishes at detailed balance.'};});
add('string-pulse',[['Pulse height (mm)',1,10,.5,4],['Gaussian width (mm)',20,100,5,50]],'Position / pulse width','Instantaneous power (W)',([A,s])=>{const tension=40,c=25;return{curves:[C('Travelling Gaussian pulse',grid(-4,4),u=>tension*c*(A/s)**2*u*u*Math.exp(-u*u))],result:'Tension 40 N, wave speed 25 m/s. Total pulse energy '+f(Math.sqrt(pi)/2*tension*(A/1000)**2/(s/1000)*1000)+' mJ. Maximum slope '+f(A/s*Math.exp(-.5))+'; the linear string approximation requires small slope.'};});
add('bead-scattering',[['Attached mass (g)',.5,10,.5,5],['String impedance (kg/s)',.1,1,.05,.5]],'Angular frequency (rad/s)','Outgoing power fraction',([m,Z])=>({curves:[C('Transmitted power',grid(0,600),w=>1/(1+(w*m/1000/(2*Z))**2)),C('Reflected power',grid(0,600),w=>1-1/(1+(w*m/1000/(2*Z))**2))],result:'Junction mass on two identical semi-infinite strings: s=ωM/(2Z), T=1/(1+s²), R=s²/(1+s²). Their sum is one.'}));
add('apparent-depth',[['Lower-medium refractive index',1.1,1.8,.05,1.35],['Physical depth (mm)',20,150,5,120]],'Incidence angle inside lower medium (degrees)','Apparent depth (mm)',([n,d])=>{const limit=Math.asin(1/n)*180/pi*.98;return{curves:[C('Back-projected emergent ray',grid(0,limit),a=>d*Math.sqrt(1-(n*Math.sin(rad(a)))**2)/(n*Math.cos(rad(a)))),C('Paraxial limit',grid(0,limit),()=>d/n)],result:'Upper medium is air. Different oblique rays back-project to different depths; the paraxial apparent depth '+f(d/n)+' mm applies to a narrow pupil.'};});
add('rectangular-spectrum',[['Spectral width (GHz)',50,300,10,100]],'Michelson mirror displacement (mm)','Signed coherence envelope',([B])=>({curves:[C('Rectangular equal-frequency spectrum',grid(-5,5,800),x=>sinc(pi*B*1e9*(2*x/1000/299792458)))],result:'Consecutive envelope nulls are separated by '+f(299792458/(2*B*1e9)*1000)+' mm. Negative signed envelopes indicate a π fringe-phase reversal; visibility is their magnitude.'}));
add('defocus-strehl',[['Numerical aperture',.05,.3,.01,.1],['Wavelength (nm)',400,800,20,500]],'Detector defocus (µm)','On-axis intensity / best focus',([NA,l])=>({curves:[C('Uniform circular pupil',grid(-100,100,700),z=>sinc(pi*z*1e-6*NA*NA/(2*l*1e-9))**2)],result:'Pupil phase span φ=πΔz NA²/λ. First axial zero at |Δz|='+f(2*l*1e-9/(NA*NA)*1e6)+' µm. Scalar paraxial diffraction with no other aberrations.'}));
add('asymmetric-cavity',[['Input field reflectivity',.1,.95,.05,.9],['Output field reflectivity',.1,.95,.05,.8]],'Round-trip phase / π','Transmitted power fraction',([a,b])=>({curves:[C('Unequal lossless cavity mirrors',grid(-2,2,1000),p=>(1-a*a)*(1-b*b)/(1+(a*b)**2-2*a*b*Math.cos(pi*p)))],result:'Peak transmission '+f((1-a*a)*(1-b*b)/(1-a*b)**2)+'. Peak reflection '+f(((a-b)/(1-a*b))**2)+'. Matched mirror amplitudes recover unit peak transmission.'}));
add('slit-resolution',[['Collimator focal length (mm)',50,300,10,100],['Incidence angle (degrees)',0,60,5,0],['Diffraction order',1,3,1,1]],'Entrance-slit width (µm)','Geometric spectral width (nm)',([fc,a,m])=>({curves:[C('1 µm grating spacing',grid(0,100),w=>Math.cos(rad(a))*w/(m*fc)),C('Diffraction scale: 500 nm, 10000 grooves',grid(0,100),()=>500/(m*10000))],result:'Geometric width d cosα w/(m fc); diffraction gives λ/(mN). Reducing the slit width eventually reaches the diffraction floor rather than an unlimited resolving power.'}));
add('knife-edge',[['Gaussian field radius (mm)',.1,1,.05,.5]],'Edge or aperture radius from beam centre (mm)','Transmitted power fraction',([w])=>({curves:[C('Straight knife edge',grid(-1.5,1.5),b=>(1-erf(Math.SQRT2*b/w))/2),C('Centred circular aperture (radius ≥0)',grid(0,1.5),a=>-Math.expm1(-2*a*a/(w*w)))],result:'Knife-edge 10–90% width = 1.2815516w = '+f(1.2815516*w)+' mm. A circular aperture integrates a different geometry from a straight edge.'}));
add('stellar-ellipse',[['Half-visibility baseline on x (m)',20,100,5,40],['Half-visibility baseline on y (m)',20,100,5,80],['Baseline direction (degrees)',0,90,5,45]],'Projected baseline length (m)','Elliptical-Gaussian fringe visibility',([x,y,a])=>{const b=1/Math.sqrt(Math.cos(rad(a))**2/x**2+Math.sin(rad(a))**2/y**2);return{curves:[C('Selected sky direction',grid(0,180),B=>Math.exp(-Math.log(2)*(B/b)**2)),C('x principal axis',grid(0,180),B=>Math.exp(-Math.log(2)*(B/x)**2)),C('y principal axis',grid(0,180),B=>Math.exp(-Math.log(2)*(B/y)**2))],result:'Half-visibility baseline along selected direction '+f(b)+' m. Gaussian intensity widths and projected baseline enter through their squared principal-axis components.'};});
})();
